INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-09', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 9', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 1, 'smooth', 'nhẵn, mịn; suôn sẻ', 'adjective', '[{"en":"Her skin felt smooth after she used the new cream.","vi":"Da cô ấy trở nên mịn màng sau khi dùng loại kem mới."},{"en":"The road was smooth, so the drive was very comfortable.","vi":"Mặt đường bằng phẳng nên lái xe rất êm."},{"en":"The new manager helped ensure a smooth transition for the team.","vi":"Người quản lý mới đã giúp cả nhóm chuyển giao suôn sẻ."}]', '[{"phrase":"smooth surface"},{"phrase":"smooth skin"},{"phrase":"smooth transition"}]', NULL, '/smuːð/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smo/smoot/smooth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 2, 'intervention', 'sự can thiệp', 'noun', '[{"en":"Early intervention can stop a small health problem from getting worse.","vi":"Can thiệp sớm có thể ngăn một vấn đề sức khỏe nhỏ trở nên nặng hơn."},{"en":"The fight ended without any intervention from the teachers.","vi":"Cuộc ẩu đả kết thúc mà không cần giáo viên can thiệp."},{"en":"The patient recovered quickly after surgical intervention.","vi":"Bệnh nhân hồi phục nhanh sau khi được can thiệp phẫu thuật."}]', '[{"phrase":"early intervention"},{"phrase":"government intervention"},{"phrase":"surgical intervention"}]', NULL, '/ˌɪntərˈvenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intervention__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 3, 'impress', 'gây ấn tượng; làm thán phục', 'verb', '[{"en":"She wore a suit to impress the interviewers.","vi":"Cô ấy mặc vest để gây ấn tượng với những người phỏng vấn."},{"en":"I was really impressed by how clean the hotel was.","vi":"Tôi thực sự ấn tượng vì khách sạn rất sạch sẽ."},{"en":"His cooking skills never fail to impress his friends.","vi":"Tài nấu ăn của anh ấy luôn khiến bạn bè thán phục."}]', '[{"phrase":"try to impress"},{"phrase":"impressed by"},{"phrase":"fail to impress"}]', 'be impressed by/with: ấn tượng với', '/ɪmˈpres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 4, 'exam', 'kỳ thi; bài thi', 'noun', '[{"en":"I have to study hard for my math exam tomorrow.","vi":"Tôi phải học chăm chỉ cho bài thi toán ngày mai."},{"en":"Did you pass your driving exam on your first try?","vi":"Bạn có đậu kỳ thi lái xe ngay lần đầu không?"},{"en":"Students are not allowed to use phones during the exam.","vi":"Học sinh không được dùng điện thoại trong lúc làm bài thi."}]', '[{"phrase":"pass an exam"},{"phrase":"final exam"},{"phrase":"driving exam"},{"phrase":"exam results"}]', NULL, '/ɪɡˈzæm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exam_/exam__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 5, 'vice', 'thói xấu; tật xấu', 'noun', '[{"en":"Chocolate is my only vice, and I eat it every day.","vi":"Sô-cô-la là thói xấu duy nhất của tôi, và ngày nào tôi cũng ăn."},{"en":"Smoking was his worst vice, but he finally quit.","vi":"Hút thuốc là tật xấu tệ nhất của anh ấy, nhưng cuối cùng anh ấy đã bỏ được."},{"en":"Laziness is a vice that can hurt your career.","vi":"Lười biếng là một thói xấu có thể ảnh hưởng đến sự nghiệp của bạn."}]', '[{"phrase":"my only vice"},{"phrase":"virtue and vice"}]', 'vice- (tiền tố) = phó: vice president (phó chủ tịch)', '/vaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/vice_/vice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 6, 'radical', 'triệt để, căn bản; cấp tiến', 'adjective', '[{"en":"The company needs radical changes to survive.","vi":"Công ty cần những thay đổi triệt để để tồn tại."},{"en":"The new teacher took a radical approach to homework.","vi":"Thầy giáo mới có cách tiếp cận hoàn toàn mới đối với bài tập về nhà."},{"en":"Some of his radical ideas surprised the older staff.","vi":"Một số ý tưởng cấp tiến của anh ấy khiến các nhân viên lớn tuổi bất ngờ."}]', '[{"phrase":"radical change"},{"phrase":"radical idea"},{"phrase":"radical approach"},{"phrase":"radical reform"}]', NULL, '/ˈrædɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radic/radical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 7, 'similarly', 'tương tự; giống nhau', 'adverb', '[{"en":"The two sisters dress similarly and often look like twins.","vi":"Hai chị em ăn mặc giống nhau và thường trông như sinh đôi."},{"en":"Prices rose last year, and similarly, rents went up sharply.","vi":"Giá cả tăng vào năm ngoái, và tương tự, tiền thuê nhà cũng tăng mạnh."},{"en":"Cats and dogs sometimes behave similarly when they feel afraid.","vi":"Mèo và chó đôi khi cư xử giống nhau khi cảm thấy sợ."}]', '[{"phrase":"behave similarly"},{"phrase":"similarly dressed"}]', NULL, '/ˈsɪmələrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similarly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 8, 'behave', 'cư xử; hành xử', 'verb', '[{"en":"The children behaved very well at the restaurant.","vi":"Bọn trẻ cư xử rất ngoan ở nhà hàng."},{"en":"Please behave yourself when your grandparents visit.","vi":"Con hãy ngoan ngoãn khi ông bà đến chơi nhé."},{"en":"He behaved badly at the party and later apologized.","vi":"Anh ấy cư xử tệ ở bữa tiệc và sau đó đã xin lỗi."}]', '[{"phrase":"behave well"},{"phrase":"behave badly"},{"phrase":"behave yourself"}]', NULL, '/bɪˈheɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behav/behave__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 9, 'loud', 'to, lớn (âm thanh); ồn ào', 'adjective', '[{"en":"The music at the party was too loud for me.","vi":"Nhạc ở bữa tiệc quá to đối với tôi."},{"en":"We heard a loud noise coming from the kitchen.","vi":"Chúng tôi nghe thấy một tiếng động lớn phát ra từ nhà bếp."},{"en":"Our neighbors are very loud late at night.","vi":"Hàng xóm nhà tôi rất ồn ào vào đêm khuya."}]', '[{"phrase":"loud noise"},{"phrase":"loud music"},{"phrase":"loud voice"},{"phrase":"out loud"}]', 'read out loud: đọc to', '/laʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lou/loud_/loud__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 10, 'dimension', 'kích thước; khía cạnh; chiều', 'noun', '[{"en":"Please measure the dimensions of the room before buying a sofa.","vi":"Hãy đo kích thước căn phòng trước khi mua ghế sofa."},{"en":"Having a baby added a new dimension to their lives.","vi":"Việc có con đã mang lại một khía cạnh mới cho cuộc sống của họ."},{"en":"The film looks amazing in three dimensions.","vi":"Bộ phim trông tuyệt vời khi xem ở dạng ba chiều."}]', '[{"phrase":"new dimension"},{"phrase":"three dimensions"},{"phrase":"exact dimensions"}]', NULL, '/daɪˈmenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimen/dimension__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 11, 'subsequent', 'sau đó; tiếp theo', 'adjective', '[{"en":"The shop did well in its first year and in subsequent years.","vi":"Cửa hàng làm ăn tốt trong năm đầu và cả những năm sau đó."},{"en":"Subsequent events proved that she had made the right choice.","vi":"Những sự việc sau đó chứng minh rằng cô ấy đã lựa chọn đúng."},{"en":"The report and the subsequent discussion took most of the meeting.","vi":"Bản báo cáo và cuộc thảo luận sau đó chiếm gần hết buổi họp."}]', '[{"phrase":"subsequent years"},{"phrase":"subsequent events"},{"phrase":"subsequent to"}]', 'subsequent to = sau khi', '/ˈsʌbsɪkwənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 12, 'infection', 'sự nhiễm trùng; bệnh nhiễm trùng', 'noun', '[{"en":"Wash the cut carefully to prevent infection.","vi":"Hãy rửa vết cắt thật kỹ để tránh nhiễm trùng."},{"en":"She missed a week of school because of an ear infection.","vi":"Cô bé nghỉ học một tuần vì bị viêm tai."},{"en":"Hand washing lowers the risk of infection in hospitals.","vi":"Rửa tay giúp giảm nguy cơ nhiễm trùng trong bệnh viện."}]', '[{"phrase":"ear infection"},{"phrase":"risk of infection"},{"phrase":"prevent infection"},{"phrase":"viral infection"}]', NULL, '/ɪnˈfekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infec/infection__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 13, 'jacket', 'áo khoác', 'noun', '[{"en":"Take a jacket because it gets cold in the evening.","vi":"Mang theo áo khoác đi vì buổi tối trời sẽ lạnh."},{"en":"He bought a leather jacket at the market.","vi":"Anh ấy mua một chiếc áo khoác da ở chợ."},{"en":"She took off her jacket and hung it by the door.","vi":"Cô ấy cởi áo khoác và treo nó cạnh cửa."}]', '[{"phrase":"leather jacket"},{"phrase":"put on a jacket"},{"phrase":"life jacket"}]', 'life jacket: áo phao', '/ˈdʒækɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jac/jacke/jacket__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 14, 'efficiency', 'hiệu quả; hiệu suất', 'noun', '[{"en":"The new software has improved the efficiency of our office.","vi":"Phần mềm mới đã nâng cao hiệu quả làm việc của văn phòng chúng tôi."},{"en":"This fridge is known for its high energy efficiency.","vi":"Chiếc tủ lạnh này nổi tiếng vì hiệu suất năng lượng cao."},{"en":"She works with great speed and efficiency.","vi":"Cô ấy làm việc rất nhanh và hiệu quả."}]', '[{"phrase":"energy efficiency"},{"phrase":"improve efficiency"},{"phrase":"fuel efficiency"}]', 'không đếm được', '/ɪˈfɪʃnsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effic/efficiency__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 15, 'dirty', 'bẩn', 'adjective', '[{"en":"Put your dirty clothes in the washing machine.","vi":"Hãy bỏ quần áo bẩn vào máy giặt."},{"en":"The kids came home with dirty hands and muddy shoes.","vi":"Bọn trẻ về nhà với đôi tay bẩn và giày dính đầy bùn."},{"en":"Nobody wants to wash the dirty dishes after dinner.","vi":"Chẳng ai muốn rửa bát đĩa bẩn sau bữa tối."}]', '[{"phrase":"dirty clothes"},{"phrase":"dirty dishes"},{"phrase":"dirty water"},{"phrase":"get dirty"}]', NULL, '/ˈdɜːrti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/dirty/dirty__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 16, 'statistic', 'số liệu thống kê', 'noun', '[{"en":"Statistics show that more people are working from home.","vi":"Số liệu thống kê cho thấy ngày càng nhiều người làm việc tại nhà."},{"en":"One surprising statistic is that most accidents happen near home.","vi":"Một số liệu đáng ngạc nhiên là phần lớn tai nạn xảy ra gần nhà."},{"en":"The report includes the latest statistics on tourism in the region.","vi":"Bản báo cáo có các số liệu thống kê mới nhất về du lịch trong khu vực."}]', '[{"phrase":"statistics show"},{"phrase":"official statistics"},{"phrase":"latest statistics"}]', 'thường dùng số nhiều: statistics', '/stəˈtɪstɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/statistic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 17, 'regularly', 'thường xuyên; đều đặn', 'adverb', '[{"en":"You should exercise regularly to stay healthy.","vi":"Bạn nên tập thể dục đều đặn để giữ sức khỏe."},{"en":"We regularly visit our grandparents on Sundays.","vi":"Chúng tôi thường xuyên đến thăm ông bà vào Chủ nhật."},{"en":"Remember to check the oil in your car regularly.","vi":"Hãy nhớ kiểm tra dầu xe ô tô thường xuyên."}]', '[{"phrase":"exercise regularly"},{"phrase":"meet regularly"},{"phrase":"regularly visit"}]', NULL, '/ˈreɡjələrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regularly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 18, 'resort', 'khu nghỉ dưỡng; giải pháp (cuối cùng)', 'noun', '[{"en":"We stayed at a beach resort for our honeymoon.","vi":"Chúng tôi ở một khu nghỉ dưỡng ven biển trong tuần trăng mật."},{"en":"The ski resort is busiest in January and February.","vi":"Khu nghỉ dưỡng trượt tuyết đông khách nhất vào tháng Một và tháng Hai."},{"en":"Borrowing money from my parents is a last resort.","vi":"Vay tiền bố mẹ là giải pháp cuối cùng của tôi."}]', '[{"phrase":"beach resort"},{"phrase":"ski resort"},{"phrase":"holiday resort"},{"phrase":"last resort"}]', 'resort to sth (v): buộc phải dùng đến', '/rɪˈzɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resor/resort__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 19, 'iron', 'sắt; bàn là', 'noun', '[{"en":"Spinach and red meat are rich in iron.","vi":"Rau chân vịt và thịt đỏ rất giàu chất sắt."},{"en":"The old gate is made of iron and is very heavy.","vi":"Chiếc cổng cũ được làm bằng sắt và rất nặng."},{"en":"Be careful, because the iron is still hot.","vi":"Cẩn thận nhé, vì bàn là vẫn còn nóng."}]', '[{"phrase":"rich in iron"},{"phrase":"cast iron"},{"phrase":"steam iron"}]', 'iron (v): là, ủi quần áo', '/ˈaɪərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iro/iron_/iron__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 20, 'broadcast', 'phát sóng; truyền hình, phát thanh', 'verb', '[{"en":"The final match will be broadcast live on TV.","vi":"Trận chung kết sẽ được phát sóng trực tiếp trên TV."},{"en":"The radio station broadcasts news every hour.","vi":"Đài phát thanh phát tin tức mỗi giờ."},{"en":"They broadcast the concert on the internet last night.","vi":"Tối qua họ đã phát sóng buổi hòa nhạc trên mạng."}]', '[{"phrase":"broadcast live"},{"phrase":"broadcast news"},{"phrase":"broadcast on television"}]', 'broadcast – broadcast – broadcast', '/ˈbrɔːdkæst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broad/broadcast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 21, 'membership', 'tư cách thành viên; hội viên', 'noun', '[{"en":"My gym membership costs thirty dollars a month.","vi":"Phí hội viên phòng gym của tôi là ba mươi đô la mỗi tháng."},{"en":"She renewed her library membership last week.","vi":"Tuần trước cô ấy đã gia hạn thẻ thành viên thư viện."},{"en":"Membership in the club is open to anyone over eighteen.","vi":"Bất kỳ ai trên mười tám tuổi đều có thể trở thành thành viên câu lạc bộ."}]', '[{"phrase":"gym membership"},{"phrase":"membership fee"},{"phrase":"membership card"}]', NULL, '/ˈmembərʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/membe/membership__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 22, 'bread', 'bánh mì', 'noun', '[{"en":"I buy fresh bread from the bakery every morning.","vi":"Sáng nào tôi cũng mua bánh mì tươi ở tiệm bánh."},{"en":"Could you pass me a slice of bread, please?","vi":"Bạn đưa giúp tôi một lát bánh mì được không?"},{"en":"My grandmother used to bake bread at home.","vi":"Bà tôi từng tự nướng bánh mì ở nhà."}]', '[{"phrase":"fresh bread"},{"phrase":"slice of bread"},{"phrase":"loaf of bread"},{"phrase":"bake bread"}]', 'không đếm được: a slice/loaf of bread', '/bred/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/bread/bread__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 23, 'blind', 'mù; không nhận ra', 'adjective', '[{"en":"The blind man crossed the street with his guide dog.","vi":"Người đàn ông khiếm thị băng qua đường cùng chú chó dẫn đường."},{"en":"My grandfather is blind in one eye.","vi":"Ông tôi bị mù một bên mắt."},{"en":"She was blind to her son''s faults.","vi":"Bà ấy không nhận ra lỗi lầm của con trai mình."}]', '[{"phrase":"go blind"},{"phrase":"blind in one eye"},{"phrase":"blind to"}]', 'blind (n): rèm cửa sổ', '/blaɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bli/blind/blind__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 24, 'pure', 'nguyên chất, tinh khiết; hoàn toàn', 'adjective', '[{"en":"This sweater is made of pure wool.","vi":"Chiếc áo len này làm từ len nguyên chất."},{"en":"The water from the mountain spring is clean and pure.","vi":"Nước từ suối trên núi sạch và tinh khiết."},{"en":"We met again at the airport by pure chance.","vi":"Chúng tôi gặp lại nhau ở sân bay hoàn toàn tình cờ."}]', '[{"phrase":"pure water"},{"phrase":"pure gold"},{"phrase":"pure chance"},{"phrase":"pure luck"}]', NULL, '/pjʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pure_/pure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 25, 'bloody', 'chảy máu, dính máu; (Anh, khẩu ngữ) chết tiệt', 'adjective', '[{"en":"He got a bloody nose playing football at school.","vi":"Cậu ấy bị chảy máu mũi khi chơi bóng đá ở trường."},{"en":"The nurse cleaned the bloody cut on her knee.","vi":"Y tá lau sạch vết cắt đang chảy máu trên đầu gối cô ấy."},{"en":"This bloody printer has stopped working again!","vi":"Cái máy in chết tiệt này lại hỏng nữa rồi!"}]', '[{"phrase":"bloody nose"},{"phrase":"bloody battle"}]', 'Nghĩa ''chết tiệt'' là tiếng lóng Anh, khá thô – nên tránh dùng', '/ˈblʌdiː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 26, 'ally', 'đồng minh; người ủng hộ', 'noun', '[{"en":"She has always been my closest ally at work.","vi":"Cô ấy luôn là đồng minh thân thiết nhất của tôi ở chỗ làm."},{"en":"The two countries have been allies for many years.","vi":"Hai nước đã là đồng minh của nhau trong nhiều năm."},{"en":"Try to find an ally before you share your idea at the meeting.","vi":"Hãy tìm một người ủng hộ trước khi trình bày ý tưởng trong cuộc họp."}]', '[{"phrase":"close ally"},{"phrase":"key ally"},{"phrase":"find an ally"}]', NULL, '/ˈælaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/ally_/ally__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 27, 'quantity', 'số lượng; lượng', 'noun', '[{"en":"The shop sells rice in large quantities.","vi":"Cửa hàng bán gạo với số lượng lớn."},{"en":"In my opinion, quality is more important than quantity.","vi":"Theo tôi, chất lượng quan trọng hơn số lượng."},{"en":"Add a small quantity of salt to the soup.","vi":"Cho một lượng muối nhỏ vào súp."}]', '[{"phrase":"in large quantities"},{"phrase":"small quantity"},{"phrase":"quality and quantity"}]', NULL, '/ˈkwɑːntəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quant/quantity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 28, 'bend', 'uốn cong; cúi xuống', 'verb', '[{"en":"Bend your knees when you lift heavy boxes.","vi":"Hãy gập đầu gối khi nhấc những thùng hàng nặng."},{"en":"She bent down to pick up the coins.","vi":"Cô ấy cúi xuống nhặt những đồng xu."},{"en":"Don''t bend the photos, or they will get damaged.","vi":"Đừng làm cong mấy tấm ảnh, kẻo chúng bị hỏng."}]', '[{"phrase":"bend down"},{"phrase":"bend your knees"},{"phrase":"bend over"},{"phrase":"bend the rules"}]', 'bend – bent – bent', '/bend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/bend_/bend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 29, 'mature', 'trưởng thành; chín chắn', 'adjective', '[{"en":"She is very mature for her age.","vi":"Cô bé rất chín chắn so với tuổi."},{"en":"It wasn''t very mature of you to shout at him.","vi":"Bạn hét vào mặt anh ấy như vậy là không chín chắn lắm."},{"en":"Mature trees provide shade in the park during summer.","vi":"Những cây trưởng thành tạo bóng mát trong công viên vào mùa hè."}]', '[{"phrase":"mature for her age"},{"phrase":"mature attitude"},{"phrase":"emotionally mature"}]', NULL, '/məˈtʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matur/mature__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-09', 30, 'briefly', 'ngắn gọn; trong chốc lát', 'adverb', '[{"en":"Could you briefly explain the plan to the new staff?","vi":"Bạn có thể giải thích ngắn gọn kế hoạch cho nhân viên mới không?"},{"en":"He stopped briefly to talk to a neighbor.","vi":"Anh ấy dừng lại một lát để nói chuyện với hàng xóm."},{"en":"We met briefly at a friend''s wedding last year.","vi":"Năm ngoái chúng tôi đã gặp nhau thoáng qua ở đám cưới của một người bạn."}]', '[{"phrase":"briefly explain"},{"phrase":"briefly describe"},{"phrase":"pause briefly"}]', NULL, '/ˈbriːfli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/briefly__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-10', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 10', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 1, 'alarm', 'đồng hồ báo thức; chuông báo động; sự lo lắng', 'noun', '[{"en":"I set my alarm for six o''clock every morning.","vi":"Tôi đặt báo thức lúc sáu giờ mỗi sáng."},{"en":"The fire alarm went off during our English class.","vi":"Chuông báo cháy reo lên trong giờ học tiếng Anh của chúng tôi."},{"en":"Her sudden weight loss caused alarm in her family.","vi":"Việc cô ấy sụt cân đột ngột khiến gia đình lo lắng."}]', '[{"phrase":"set the alarm"},{"phrase":"fire alarm"},{"phrase":"alarm clock"},{"phrase":"cause alarm"}]', NULL, '/əˈlɑːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ala/alarm/alarm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 2, 'disturb', 'làm phiền; quấy rầy; làm xáo trộn', 'verb', '[{"en":"Please don''t disturb me while I''m working.","vi":"Làm ơn đừng làm phiền tôi khi tôi đang làm việc."},{"en":"Sorry to disturb you, but can I ask a quick question?","vi":"Xin lỗi đã làm phiền, nhưng tôi hỏi nhanh một câu được không?"},{"en":"The noise from the street disturbed our sleep all night.","vi":"Tiếng ồn ngoài đường quấy rầy giấc ngủ của chúng tôi suốt đêm."}]', '[{"phrase":"sorry to disturb you"},{"phrase":"do not disturb"},{"phrase":"disturb someone''s sleep"}]', NULL, '/dɪˈstɜːrb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distu/disturb__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 3, 'sustain', 'duy trì; chịu (thương tích, thiệt hại)', 'verb', '[{"en":"It is hard to sustain this level of growth for long.","vi":"Rất khó để duy trì mức tăng trưởng này trong thời gian dài."},{"en":"We need more money to sustain the project next year.","vi":"Chúng tôi cần thêm tiền để duy trì dự án vào năm sau."},{"en":"The driver sustained serious injuries in the accident.","vi":"Người lái xe bị thương nặng trong vụ tai nạn."}]', '[{"phrase":"sustain growth"},{"phrase":"sustain injuries"},{"phrase":"sustain damage"},{"phrase":"sustain interest"}]', NULL, '/səˈsteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/susta/sustain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 4, 'flood', 'lũ lụt; sự tràn ngập, dòng ồ ạt', 'noun', '[{"en":"The flood destroyed hundreds of homes in the valley.","vi":"Trận lũ đã phá hủy hàng trăm ngôi nhà trong thung lũng."},{"en":"Many farmers lost their crops in last year''s floods.","vi":"Nhiều nông dân mất mùa vì những trận lũ năm ngoái."},{"en":"After the article appeared, the office received a flood of emails.","vi":"Sau khi bài báo được đăng, văn phòng nhận được vô số email."}]', '[{"phrase":"flood warning"},{"phrase":"flash flood"},{"phrase":"a flood of"},{"phrase":"flood damage"}]', 'cũng là động từ: làm ngập, tràn vào', '/flʌd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flood/flood__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 5, 'poverty', 'sự nghèo đói; cảnh nghèo khó', 'noun', '[{"en":"Millions of children around the world still live in poverty.","vi":"Hàng triệu trẻ em trên thế giới vẫn sống trong cảnh nghèo đói."},{"en":"He grew up in poverty but worked hard to succeed.","vi":"Anh ấy lớn lên trong nghèo khó nhưng đã làm việc chăm chỉ để thành công."},{"en":"Education is one of the best ways out of poverty.","vi":"Giáo dục là một trong những con đường tốt nhất để thoát nghèo."}]', '[{"phrase":"live in poverty"},{"phrase":"extreme poverty"},{"phrase":"poverty line"},{"phrase":"reduce poverty"}]', 'không đếm được', '/ˈpɑːvərti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pov/pover/poverty__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 6, 'crazy', 'điên; điên rồ; mê (cái gì)', 'adjective', '[{"en":"It''s crazy to drive that fast in the rain.","vi":"Lái xe nhanh như vậy dưới trời mưa thật là điên rồ."},{"en":"The noise from next door is driving me crazy.","vi":"Tiếng ồn từ nhà bên cạnh làm tôi phát điên."},{"en":"My little brother is crazy about football.","vi":"Em trai tôi mê bóng đá lắm."}]', '[{"phrase":"go crazy"},{"phrase":"drive someone crazy"},{"phrase":"crazy about"},{"phrase":"crazy idea"}]', NULL, '/ˈkreɪzi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crazy/crazy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 7, 'cite', 'trích dẫn; viện dẫn, nêu ra', 'verb', '[{"en":"You must cite all your sources at the end of the essay.","vi":"Bạn phải trích dẫn tất cả các nguồn ở cuối bài luận."},{"en":"The article cites a study from a well-known university.","vi":"Bài báo trích dẫn một nghiên cứu của một trường đại học nổi tiếng."},{"en":"She cited family reasons for leaving her job.","vi":"Cô ấy viện lý do gia đình khi nghỉ việc."}]', '[{"phrase":"cite a source"},{"phrase":"cite an example"},{"phrase":"cite reasons"},{"phrase":"widely cited"}]', NULL, '/saɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/cite_/cite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 8, 'newly', 'mới, vừa mới', 'adverb', '[{"en":"The newly built library opens to the public next week.","vi":"Thư viện mới xây sẽ mở cửa cho công chúng vào tuần tới."},{"en":"We met a newly married couple on our trip.","vi":"Chúng tôi gặp một cặp vợ chồng mới cưới trong chuyến đi."},{"en":"Newly arrived students can get help from the student center.","vi":"Sinh viên mới đến có thể nhờ trung tâm sinh viên hỗ trợ."}]', '[{"phrase":"newly built"},{"phrase":"newly married"},{"phrase":"newly arrived"},{"phrase":"newly elected"}]', NULL, '/ˈnuːli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/newly/newly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 9, 'parallel', 'song song; tương tự', 'adjective', '[{"en":"Draw two parallel lines on your paper.","vi":"Hãy vẽ hai đường thẳng song song trên giấy."},{"en":"The road runs parallel to the river for several miles.","vi":"Con đường chạy song song với dòng sông suốt vài dặm."},{"en":"The two cities went through parallel changes during the same period.","vi":"Hai thành phố đã trải qua những thay đổi tương tự trong cùng thời kỳ."}]', '[{"phrase":"parallel lines"},{"phrase":"parallel to"},{"phrase":"run parallel"}]', NULL, '/ˈpærəlel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paral/parallel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 10, 'gender', 'giới tính; giới', 'noun', '[{"en":"Everyone should get equal pay regardless of gender.","vi":"Mọi người nên được trả lương ngang nhau bất kể giới tính."},{"en":"The form asks for your name, age and gender.","vi":"Mẫu đơn hỏi tên, tuổi và giới tính của bạn."},{"en":"Gender equality is an important goal for many companies.","vi":"Bình đẳng giới là mục tiêu quan trọng của nhiều công ty."}]', '[{"phrase":"gender equality"},{"phrase":"gender gap"},{"phrase":"regardless of gender"},{"phrase":"gender roles"}]', NULL, '/ˈdʒendər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gende/gender__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 11, 'sponsor', 'nhà tài trợ', 'noun', '[{"en":"The team is looking for a new sponsor for next season.","vi":"Đội bóng đang tìm nhà tài trợ mới cho mùa giải tới."},{"en":"A local bank is the main sponsor of the festival.","vi":"Một ngân hàng địa phương là nhà tài trợ chính của lễ hội."},{"en":"Our school found sponsors to pay for the concert.","vi":"Trường chúng tôi đã tìm được nhà tài trợ để chi trả cho buổi hòa nhạc."}]', '[{"phrase":"main sponsor"},{"phrase":"corporate sponsor"},{"phrase":"find a sponsor"},{"phrase":"official sponsor"}]', 'cũng là động từ: sponsor an event (tài trợ một sự kiện)', '/ˈspɑːnsər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/spons/sponsor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 12, 'boot', 'giày ống, bốt, ủng; cốp xe', 'noun', '[{"en":"Wear your boots because the path will be muddy.","vi":"Hãy mang ủng vì con đường sẽ lầy lội."},{"en":"She bought a pair of leather boots for winter.","vi":"Cô ấy đã mua một đôi bốt da cho mùa đông."},{"en":"Can you put the suitcases in the boot, please?","vi":"Bạn để mấy cái vali vào cốp xe giúp tôi nhé?"}]', '[{"phrase":"a pair of boots"},{"phrase":"leather boots"},{"phrase":"hiking boots"},{"phrase":"car boot"}]', 'cốp xe: Anh boot · Mỹ trunk', '/buːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boot_/boot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 13, 'accurate', 'chính xác', 'adjective', '[{"en":"The weather forecast was surprisingly accurate this week.","vi":"Dự báo thời tiết tuần này chính xác đến bất ngờ."},{"en":"Please make sure all the information on the form is accurate.","vi":"Hãy đảm bảo mọi thông tin trong mẫu đơn đều chính xác."},{"en":"It is difficult to give an accurate number right now.","vi":"Hiện giờ rất khó đưa ra một con số chính xác."}]', '[{"phrase":"accurate information"},{"phrase":"highly accurate"},{"phrase":"accurate description"},{"phrase":"fairly accurate"}]', NULL, '/ˈækjərət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accur/accurate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 14, 'dealer', 'đại lý; người buôn bán', 'noun', '[{"en":"We bought our car from a dealer near the city center.","vi":"Chúng tôi mua xe ở một đại lý gần trung tâm thành phố."},{"en":"My uncle is an antique dealer in a small town.","vi":"Chú tôi là người buôn đồ cổ ở một thị trấn nhỏ."},{"en":"The dealer offered us a good price for our old car.","vi":"Đại lý trả cho chúng tôi một giá tốt để mua lại chiếc xe cũ."}]', '[{"phrase":"car dealer"},{"phrase":"antique dealer"},{"phrase":"art dealer"}]', NULL, '/ˈdiːlər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/deale/dealer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 15, 'button', 'nút bấm; cúc áo', 'noun', '[{"en":"Press the green button to start the machine.","vi":"Nhấn nút màu xanh lá để khởi động máy."},{"en":"Click the button below to download the file.","vi":"Nhấp vào nút bên dưới để tải tệp xuống."},{"en":"One of the buttons on my shirt fell off.","vi":"Một chiếc cúc trên áo sơ mi của tôi bị bung ra."}]', '[{"phrase":"press a button"},{"phrase":"click the button"},{"phrase":"push a button"},{"phrase":"sew on a button"}]', NULL, '/ˈbʌtn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/but/butto/button__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 16, 'burden', 'gánh nặng', 'noun', '[{"en":"I don''t want to be a burden to my children.","vi":"Tôi không muốn trở thành gánh nặng cho con cái."},{"en":"The new tax will put a heavy burden on small businesses.","vi":"Thuế mới sẽ đặt gánh nặng lớn lên các doanh nghiệp nhỏ."},{"en":"She carried the burden of her family''s debts for years.","vi":"Cô ấy đã gánh khoản nợ của gia đình suốt nhiều năm."}]', '[{"phrase":"heavy burden"},{"phrase":"a burden on"},{"phrase":"financial burden"},{"phrase":"reduce the burden"}]', NULL, '/ˈbɜːrdn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burde/burden__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 17, 'desert', 'sa mạc', 'noun', '[{"en":"Very little rain falls in the desert.","vi":"Ở sa mạc rất ít khi có mưa."},{"en":"We rode camels across the desert at sunset.","vi":"Chúng tôi cưỡi lạc đà băng qua sa mạc lúc hoàng hôn."},{"en":"It gets surprisingly cold in the desert at night.","vi":"Ban đêm ở sa mạc trời lạnh đến bất ngờ."}]', '[{"phrase":"in the desert"},{"phrase":"across the desert"},{"phrase":"desert island"}]', 'desert (sa mạc) ≠ dessert (món tráng miệng)', '/ˈdezərt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/deser/desert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 18, 'mate', 'bạn, bạn bè (thân mật); bạn tình (động vật)', 'noun', '[{"en":"He went on vacation with his best mate from school.","vi":"Anh ấy đi nghỉ với người bạn thân nhất thời đi học."},{"en":"Thanks, mate, I really appreciate your help.","vi":"Cảm ơn nhé bạn, mình thật sự biết ơn sự giúp đỡ của bạn."},{"en":"Male birds sing loudly to attract a mate.","vi":"Chim trống hót to để thu hút bạn tình."}]', '[{"phrase":"best mate"},{"phrase":"old mate"},{"phrase":"attract a mate"},{"phrase":"find a mate"}]', 'nghĩa ''bạn'' là thân mật, phổ biến ở Anh và Úc', '/meɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mate_/mate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 19, 'occasionally', 'thỉnh thoảng, đôi khi', 'adverb', '[{"en":"I occasionally work from home on Fridays.","vi":"Thỉnh thoảng tôi làm việc ở nhà vào thứ Sáu."},{"en":"We still see each other occasionally, but not very often.","vi":"Chúng tôi vẫn thỉnh thoảng gặp nhau, nhưng không thường xuyên lắm."},{"en":"My father only occasionally drinks coffee after dinner.","vi":"Bố tôi chỉ thỉnh thoảng uống cà phê sau bữa tối."}]', '[{"phrase":"only occasionally"},{"phrase":"very occasionally"},{"phrase":"occasionally visit"}]', NULL, '/əˈkeɪʒnəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occas/occasionally__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 20, 'shareholder', 'cổ đông', 'noun', '[{"en":"The company made a big profit for its shareholders this year.","vi":"Năm nay công ty đã mang lại lợi nhuận lớn cho các cổ đông."},{"en":"Shareholders will vote on the new plan next month.","vi":"Các cổ đông sẽ bỏ phiếu về kế hoạch mới vào tháng tới."},{"en":"She became the largest shareholder after buying more shares.","vi":"Cô ấy trở thành cổ đông lớn nhất sau khi mua thêm cổ phần."}]', '[{"phrase":"major shareholder"},{"phrase":"largest shareholder"},{"phrase":"shareholder value"}]', NULL, '/ˈʃerhəʊldər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/share/shareholder__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 21, 'bowl', 'cái bát, cái tô', 'noun', '[{"en":"I usually have a bowl of cereal for breakfast.","vi":"Tôi thường ăn một bát ngũ cốc vào bữa sáng."},{"en":"Put the eggs and sugar in a large bowl.","vi":"Cho trứng và đường vào một cái tô lớn."},{"en":"Don''t forget to fill the dog''s water bowl.","vi":"Đừng quên đổ đầy bát nước của con chó."}]', '[{"phrase":"a bowl of"},{"phrase":"soup bowl"},{"phrase":"mixing bowl"},{"phrase":"salad bowl"}]', NULL, '/bəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bow/bowl_/bowl__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 22, 'discovery', 'sự khám phá; phát hiện', 'noun', '[{"en":"Scientists made an important discovery about the ocean floor.","vi":"Các nhà khoa học đã có một phát hiện quan trọng về đáy đại dương."},{"en":"The discovery of old coins surprised everyone in the village.","vi":"Việc phát hiện những đồng xu cổ khiến cả làng ngạc nhiên."},{"en":"The children were excited about their discovery in the garden.","vi":"Bọn trẻ rất hào hứng với thứ chúng phát hiện ra trong vườn."}]', '[{"phrase":"make a discovery"},{"phrase":"important discovery"},{"phrase":"scientific discovery"}]', NULL, '/dɪˈskʌvəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discovery__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 23, 'resistance', 'sự phản đối, kháng cự; sức đề kháng', 'noun', '[{"en":"The plan met strong resistance from local residents.","vi":"Kế hoạch vấp phải sự phản đối mạnh mẽ từ người dân địa phương."},{"en":"People often show resistance to change at work.","vi":"Ở nơi làm việc, người ta thường chống lại sự thay đổi."},{"en":"Eating well can improve your body''s resistance to disease.","vi":"Ăn uống tốt có thể tăng sức đề kháng của cơ thể trước bệnh tật."}]', '[{"phrase":"strong resistance"},{"phrase":"resistance to change"},{"phrase":"meet resistance"}]', NULL, '/rɪˈzɪstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resis/resistance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 24, 'bath', 'sự tắm (trong bồn); bồn tắm', 'noun', '[{"en":"I like to take a hot bath after a long day.","vi":"Tôi thích tắm nước nóng sau một ngày dài."},{"en":"It''s time to give the baby a bath.","vi":"Đến giờ tắm cho em bé rồi."},{"en":"The bath in our hotel room was very small.","vi":"Bồn tắm trong phòng khách sạn của chúng tôi rất nhỏ."}]', '[{"phrase":"take a bath"},{"phrase":"have a bath"},{"phrase":"hot bath"},{"phrase":"run a bath"}]', 'bồn tắm: Anh bath · Mỹ bathtub', '/bæθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bat/bath_/bath__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 25, 'frequency', 'tần suất; tần số', 'noun', '[{"en":"The frequency of heavy storms has increased in recent years.","vi":"Tần suất các cơn bão lớn đã tăng lên trong những năm gần đây."},{"en":"The app lets you choose the frequency of notifications.","vi":"Ứng dụng cho phép bạn chọn tần suất nhận thông báo."},{"en":"Dogs can hear sounds at a much higher frequency than humans.","vi":"Chó có thể nghe được âm thanh ở tần số cao hơn nhiều so với con người."}]', '[{"phrase":"high frequency"},{"phrase":"low frequency"},{"phrase":"radio frequency"},{"phrase":"increase in frequency"}]', NULL, '/ˈfriːkwənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequency__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 26, 'criticize', 'chỉ trích; phê bình, chê', 'verb', '[{"en":"The new movie was heavily criticized for being too long.","vi":"Bộ phim mới bị chỉ trích nặng nề vì quá dài."},{"en":"My boss criticized me for missing the deadline.","vi":"Sếp phê bình tôi vì trễ hạn."},{"en":"Please don''t criticize my cooking in front of our guests.","vi":"Làm ơn đừng chê món tôi nấu trước mặt khách."}]', '[{"phrase":"criticize someone for"},{"phrase":"heavily criticized"},{"phrase":"widely criticized"},{"phrase":"strongly criticize"}]', 'Anh: criticise · Mỹ: criticize', '/ˈkrɪtɪsaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/criticize__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 27, 'tap', 'gõ nhẹ, vỗ nhẹ; chạm (màn hình)', 'verb', '[{"en":"Someone tapped me on the shoulder at the bus stop.","vi":"Có người vỗ nhẹ vào vai tôi ở trạm xe buýt."},{"en":"She tapped on the window to get my attention.","vi":"Cô ấy gõ nhẹ vào cửa sổ để thu hút sự chú ý của tôi."},{"en":"Tap the icon to open the app.","vi":"Chạm vào biểu tượng để mở ứng dụng."}]', '[{"phrase":"tap someone on the shoulder"},{"phrase":"tap the screen"},{"phrase":"tap your foot"},{"phrase":"tap on the door"}]', 'tap – tapped; danh từ: vòi nước (Mỹ: faucet)', '/tæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tap__/tap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 28, 'philosophy', 'triết học; triết lý', 'noun', '[{"en":"She studied philosophy at university before becoming a teacher.","vi":"Cô ấy học triết học ở đại học trước khi trở thành giáo viên."},{"en":"My philosophy is to enjoy every day as it comes.","vi":"Triết lý của tôi là tận hưởng từng ngày trôi qua."},{"en":"The company''s philosophy is to put customers first.","vi":"Triết lý của công ty là đặt khách hàng lên hàng đầu."}]', '[{"phrase":"study philosophy"},{"phrase":"philosophy of life"},{"phrase":"business philosophy"}]', NULL, '/fəˈlɑːsəfi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phi/philo/philosophy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 29, 'lip', 'môi', 'noun', '[{"en":"Her lips were dry from the cold wind.","vi":"Môi cô ấy bị khô vì gió lạnh."},{"en":"He bit his lip to stop himself from laughing.","vi":"Anh ấy cắn môi để nhịn cười."},{"en":"She put a finger to her lips to tell us to be quiet.","vi":"Cô ấy đặt ngón tay lên môi để bảo chúng tôi im lặng."}]', '[{"phrase":"bite your lip"},{"phrase":"upper lip"},{"phrase":"lower lip"},{"phrase":"dry lips"}]', NULL, '/lɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lip/lip__/lip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-10', 30, 'attribute', 'cho là do; quy cho (là của ai)', 'verb', '[{"en":"She attributes her success to years of hard work.","vi":"Cô ấy cho rằng thành công của mình là nhờ nhiều năm làm việc chăm chỉ."},{"en":"The delay was attributed to bad weather.","vi":"Sự chậm trễ được cho là do thời tiết xấu."},{"en":"This painting is often attributed to a famous Italian artist.","vi":"Bức tranh này thường được cho là của một họa sĩ nổi tiếng người Ý."}]', '[{"phrase":"attribute something to"},{"phrase":"be attributed to"},{"phrase":"largely attributed to"}]', 'attribute to sth · danh từ: thuộc tính, phẩm chất', '/əˈtrɪbjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attri/attribute__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-11', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 11', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 1, 'apologize', 'xin lỗi', 'verb', '[{"en":"I apologized to my sister for forgetting her birthday.","vi":"Tôi đã xin lỗi em gái vì quên sinh nhật của em ấy."},{"en":"You should apologize for being so rude to him.","vi":"Bạn nên xin lỗi vì đã quá thô lỗ với anh ấy."},{"en":"We apologize for the delay and thank you for waiting.","vi":"Chúng tôi xin lỗi vì sự chậm trễ và cảm ơn bạn đã chờ đợi."}]', '[{"phrase":"apologize for the delay"},{"phrase":"apologize to someone"},{"phrase":"sincerely apologize"}]', 'apologize to sb for sth · Anh: apologise', '/əˈpɑːlədʒaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apo/apolo/apologize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 2, 'approval', 'sự chấp thuận; sự tán thành', 'noun', '[{"en":"The plan still needs approval from the manager.","vi":"Kế hoạch vẫn cần sự chấp thuận của người quản lý."},{"en":"We finally got approval to build a new garage.","vi":"Cuối cùng chúng tôi cũng được chấp thuận xây một nhà để xe mới."},{"en":"As a boy, he always wanted his father''s approval.","vi":"Hồi nhỏ, cậu ấy luôn mong nhận được sự tán thành của bố."}]', '[{"phrase":"need approval"},{"phrase":"get approval"},{"phrase":"final approval"}]', NULL, '/əˈpruːvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approval__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 3, 'grab', 'chộp lấy; túm lấy; ăn/uống vội', 'verb', '[{"en":"She grabbed her bag and ran out the door.","vi":"Cô ấy chộp lấy túi xách và chạy ra khỏi cửa."},{"en":"He grabbed my arm to stop me from falling.","vi":"Anh ấy túm lấy tay tôi để tôi không bị ngã."},{"en":"Let''s grab a coffee before the meeting starts.","vi":"Mình tranh thủ uống cà phê trước khi cuộc họp bắt đầu nhé."}]', '[{"phrase":"grab a coffee"},{"phrase":"grab a bite"},{"phrase":"grab someone''s arm"},{"phrase":"grab attention"}]', NULL, '/ɡræb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grab_/grab__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 4, 'entitle', 'cho quyền; đặt tựa đề', 'verb', '[{"en":"This ticket entitles you to one free drink.","vi":"Vé này cho bạn quyền nhận một đồ uống miễn phí."},{"en":"All workers are entitled to paid holidays.","vi":"Tất cả công nhân đều có quyền được nghỉ lễ có lương."},{"en":"Her first novel was entitled ''Summer by the Sea''.","vi":"Cuốn tiểu thuyết đầu tay của cô ấy có tựa đề ''Summer by the Sea''."}]', '[{"phrase":"be entitled to"},{"phrase":"entitle someone to something"},{"phrase":"fully entitled"}]', 'be entitled to + N/V: có quyền (làm/nhận) gì', '/ɪnˈtaɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entit/entitle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 5, 'lend', 'cho mượn; cho vay', 'verb', '[{"en":"Could you lend me your pen for a minute?","vi":"Bạn có thể cho mình mượn cây bút một lát không?"},{"en":"My brother lent me some money to buy a car.","vi":"Anh trai đã cho tôi vay một ít tiền để mua xe."},{"en":"The bank refused to lend us any more money.","vi":"Ngân hàng từ chối cho chúng tôi vay thêm tiền."}]', '[{"phrase":"lend money"},{"phrase":"lend a hand"},{"phrase":"lend someone something"}]', 'lend – lent – lent · lend (cho mượn) ≠ borrow (mượn)', '/lend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/len/lend_/lend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 6, 'involvement', 'sự tham gia; sự dính líu', 'noun', '[{"en":"Parents'' involvement in school activities helps children learn better.","vi":"Sự tham gia của phụ huynh vào các hoạt động ở trường giúp trẻ học tốt hơn."},{"en":"Thank you for your involvement in this project.","vi":"Cảm ơn bạn đã tham gia vào dự án này."},{"en":"The manager denied any involvement in the decision.","vi":"Người quản lý phủ nhận mọi dính líu đến quyết định đó."}]', '[{"phrase":"involvement in"},{"phrase":"active involvement"},{"phrase":"deny any involvement"},{"phrase":"parental involvement"}]', NULL, '/ɪnˈvɑːlvmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involvement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 7, 'exposure', 'sự tiếp xúc; sự xuất hiện trước công chúng', 'noun', '[{"en":"Too much exposure to the sun can damage your skin.","vi":"Tiếp xúc quá nhiều với ánh nắng có thể làm hại da của bạn."},{"en":"Living abroad gave her daily exposure to English.","vi":"Sống ở nước ngoài giúp cô ấy được tiếp xúc với tiếng Anh hằng ngày."},{"en":"The small band got a lot of exposure on social media.","vi":"Ban nhạc nhỏ được xuất hiện rất nhiều trên mạng xã hội."}]', '[{"phrase":"exposure to"},{"phrase":"sun exposure"},{"phrase":"media exposure"},{"phrase":"long-term exposure"}]', NULL, '/ɪkˈspəʊʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/exposure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 8, 'conventional', 'thông thường; truyền thống', 'adjective', '[{"en":"Electric cars are much quieter than conventional cars.","vi":"Xe điện chạy êm hơn nhiều so với xe thông thường."},{"en":"My parents have very conventional ideas about marriage.","vi":"Bố mẹ tôi có những quan niệm rất truyền thống về hôn nhân."},{"en":"Our teacher does not like conventional teaching methods.","vi":"Giáo viên của chúng tôi không thích các phương pháp giảng dạy truyền thống."}]', '[{"phrase":"conventional methods"},{"phrase":"conventional wisdom"},{"phrase":"conventional medicine"}]', NULL, '/kənˈvenʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconventional__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 9, 'digital', 'kỹ thuật số; số', 'adjective', '[{"en":"My grandfather finally bought a digital camera last year.","vi":"Năm ngoái cuối cùng ông tôi cũng mua một chiếc máy ảnh kỹ thuật số."},{"en":"The library offers a large collection of digital books.","vi":"Thư viện có một bộ sưu tập lớn sách điện tử."},{"en":"Children today are growing up in a digital world.","vi":"Trẻ em ngày nay đang lớn lên trong một thế giới số."}]', '[{"phrase":"digital camera"},{"phrase":"digital technology"},{"phrase":"digital age"},{"phrase":"digital world"}]', NULL, '/ˈdɪdʒɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dig/digit/digital__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 10, 'translate', 'dịch; chuyển thành', 'verb', '[{"en":"Can you translate this letter into English for me?","vi":"Bạn có thể dịch bức thư này sang tiếng Anh giúp tôi không?"},{"en":"Her books have been translated into twenty languages.","vi":"Sách của cô ấy đã được dịch ra hai mươi thứ tiếng."},{"en":"Good ideas do not always translate into success.","vi":"Ý tưởng hay không phải lúc nào cũng mang lại thành công."}]', '[{"phrase":"translate into"},{"phrase":"translate from"},{"phrase":"translate a book"},{"phrase":"roughly translate"}]', NULL, '/trænzˈleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/translate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 11, 'edit', 'chỉnh sửa; biên tập', 'verb', '[{"en":"I need to edit this video before I post it.","vi":"Tôi cần chỉnh sửa video này trước khi đăng lên."},{"en":"She edits a small magazine about gardening.","vi":"Cô ấy biên tập một tạp chí nhỏ về làm vườn."},{"en":"Could you edit my essay and check the grammar?","vi":"Bạn có thể chỉnh sửa bài luận và kiểm tra ngữ pháp giúp tôi không?"}]', '[{"phrase":"edit a video"},{"phrase":"edit photos"},{"phrase":"edit a book"}]', NULL, '/ˈedɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edit_/edit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 12, 'formation', 'sự hình thành; đội hình', 'noun', '[{"en":"The teacher explained the formation of clouds in simple words.","vi":"Giáo viên giải thích sự hình thành của mây bằng những từ ngữ đơn giản."},{"en":"Cold air can lead to the formation of ice on roads.","vi":"Không khí lạnh có thể khiến băng hình thành trên đường."},{"en":"The birds flew south in a V formation.","vi":"Đàn chim bay về phía nam theo đội hình chữ V."}]', '[{"phrase":"the formation of"},{"phrase":"in formation"},{"phrase":"rock formation"}]', NULL, '/fɔːrˈmeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/formation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 13, 'deposit', 'tiền đặt cọc; tiền gửi (ngân hàng)', 'noun', '[{"en":"We paid a deposit of two hundred dollars for the apartment.","vi":"Chúng tôi đã trả hai trăm đô la tiền đặt cọc cho căn hộ."},{"en":"You will get your deposit back when you return the bike.","vi":"Bạn sẽ được nhận lại tiền cọc khi trả xe đạp."},{"en":"She made a deposit at the bank this morning.","vi":"Sáng nay cô ấy đã gửi tiền vào ngân hàng."}]', '[{"phrase":"pay a deposit"},{"phrase":"make a deposit"},{"phrase":"security deposit"}]', NULL, '/dɪˈpɑːzɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depos/deposit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 14, 'pleasant', 'dễ chịu; vui vẻ; dễ mến', 'adjective', '[{"en":"We had a pleasant evening with our neighbors.","vi":"Chúng tôi đã có một buổi tối vui vẻ với hàng xóm."},{"en":"The weather was warm and pleasant all week.","vi":"Thời tiết ấm áp và dễ chịu suốt cả tuần."},{"en":"The woman at the front desk was very pleasant.","vi":"Người phụ nữ ở quầy lễ tân rất dễ mến."}]', '[{"phrase":"pleasant surprise"},{"phrase":"pleasant evening"},{"phrase":"pleasant weather"}]', NULL, '/ˈpleznt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/pleasant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 15, 'overseas', 'ở nước ngoài; ra nước ngoài', 'adverb', '[{"en":"My cousin has been working overseas for five years.","vi":"Anh họ tôi đã làm việc ở nước ngoài được năm năm."},{"en":"Many students want to study overseas after high school.","vi":"Nhiều học sinh muốn đi học ở nước ngoài sau khi học xong cấp ba."},{"en":"The company sells most of its products overseas.","vi":"Công ty bán phần lớn sản phẩm của mình ra nước ngoài."}]', '[{"phrase":"work overseas"},{"phrase":"study overseas"},{"phrase":"travel overseas"},{"phrase":"overseas students"}]', 'cũng là tính từ: overseas students = sinh viên nước ngoài', '/ˌəʊvərˈsiːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overs/overseas__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 16, 'advocate', 'ủng hộ; chủ trương', 'verb', '[{"en":"Many doctors advocate a diet low in sugar.","vi":"Nhiều bác sĩ ủng hộ chế độ ăn ít đường."},{"en":"The group advocates more bike lanes in the city.","vi":"Nhóm này ủng hộ việc có thêm làn đường dành cho xe đạp trong thành phố."},{"en":"Our teacher strongly advocates reading for pleasure every day.","vi":"Giáo viên của chúng tôi rất ủng hộ việc đọc sách để giải trí mỗi ngày."}]', '[{"phrase":"strongly advocate"},{"phrase":"advocate the use of"},{"phrase":"advocate change"}]', 'danh từ: advocate = người ủng hộ; luật sư bào chữa', '/ˈædvəkət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advoc/advocate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 17, 'establishment', 'sự thành lập; cơ sở (kinh doanh)', 'noun', '[{"en":"The establishment of the new hospital took three years.","vi":"Việc thành lập bệnh viện mới mất ba năm."},{"en":"Since its establishment, the school has trained thousands of nurses.","vi":"Kể từ khi thành lập, trường đã đào tạo hàng nghìn y tá."},{"en":"This restaurant is one of the oldest establishments in town.","vi":"Nhà hàng này là một trong những cơ sở lâu đời nhất trong thị trấn."}]', '[{"phrase":"the establishment of"},{"phrase":"business establishment"},{"phrase":"educational establishment"}]', NULL, '/ɪˈstæblɪʃmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establishment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 18, 'summary', 'bản tóm tắt', 'noun', '[{"en":"Please write a short summary of the article.","vi":"Hãy viết một bản tóm tắt ngắn về bài báo."},{"en":"Here is a summary of what we discussed today.","vi":"Đây là bản tóm tắt những gì chúng ta đã thảo luận hôm nay."},{"en":"In summary, the trip was a great success.","vi":"Tóm lại, chuyến đi rất thành công."}]', '[{"phrase":"short summary"},{"phrase":"brief summary"},{"phrase":"in summary"},{"phrase":"summary of"}]', NULL, '/ˈsʌməri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summary__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 19, 'rough', 'thô ráp; phỏng chừng; vất vả', 'adjective', '[{"en":"The skin on his hands was rough from years of work.","vi":"Da tay anh ấy thô ráp sau nhiều năm lao động."},{"en":"Can you give me a rough idea of the cost?","vi":"Bạn có thể cho tôi biết sơ bộ chi phí khoảng bao nhiêu không?"},{"en":"She has had a rough week at work.","vi":"Cô ấy vừa trải qua một tuần làm việc vất vả."}]', '[{"phrase":"rough idea"},{"phrase":"rough estimate"},{"phrase":"rough surface"},{"phrase":"rough day"}]', NULL, '/rʌf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/rough/rough__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 20, 'pen', 'bút; bút mực', 'noun', '[{"en":"Do you have a pen I could borrow?","vi":"Bạn có cây bút nào cho mình mượn không?"},{"en":"Please fill in the form with a black pen.","vi":"Vui lòng điền vào mẫu đơn bằng bút mực đen."},{"en":"My pen ran out of ink during the exam.","vi":"Bút của tôi hết mực trong lúc thi."}]', '[{"phrase":"black pen"},{"phrase":"ballpoint pen"},{"phrase":"pen and paper"}]', NULL, '/pen/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pen/pen__/pen__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 21, 'recovery', 'sự hồi phục; sự phục hồi', 'noun', '[{"en":"She made a quick recovery after the operation.","vi":"Cô ấy hồi phục nhanh chóng sau ca phẫu thuật."},{"en":"We all wish you a speedy recovery, Grandma.","vi":"Cả nhà chúc bà mau chóng hồi phục ạ."},{"en":"The town''s economy is showing signs of recovery.","vi":"Nền kinh tế của thị trấn đang có dấu hiệu phục hồi."}]', '[{"phrase":"make a recovery"},{"phrase":"speedy recovery"},{"phrase":"full recovery"},{"phrase":"economic recovery"}]', NULL, '/rɪˈkʌvəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recovery__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 22, 'seal', 'dán kín; đóng kín; niêm phong', 'verb', '[{"en":"She sealed the envelope and put a stamp on it.","vi":"Cô ấy dán kín phong bì rồi dán tem lên."},{"en":"Keep the cookies in a tightly sealed box.","vi":"Hãy để bánh quy trong hộp được đậy thật kín."},{"en":"Seal the bag well so the food stays fresh.","vi":"Hãy đóng kín túi để thức ăn luôn tươi."}]', '[{"phrase":"seal an envelope"},{"phrase":"tightly sealed"},{"phrase":"seal off"}]', 'danh từ: seal = con hải cẩu; con dấu', '/siːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seal_/seal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 23, 'tube', 'ống; tuýp', 'noun', '[{"en":"I need to buy a new tube of toothpaste.","vi":"Tôi cần mua một tuýp kem đánh răng mới."},{"en":"Water flows through this plastic tube into the tank.","vi":"Nước chảy qua ống nhựa này vào bể."},{"en":"She squeezed the last bit of paint out of the tube.","vi":"Cô ấy nặn chút màu vẽ cuối cùng ra khỏi tuýp."}]', '[{"phrase":"tube of toothpaste"},{"phrase":"plastic tube"},{"phrase":"rubber tube"},{"phrase":"test tube"}]', NULL, '/tuːb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tub/tube_/tube__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 24, 'tower', 'tháp; tòa nhà cao tầng', 'noun', '[{"en":"From the top of the tower, you can see the whole city.","vi":"Từ đỉnh tháp, bạn có thể nhìn thấy toàn bộ thành phố."},{"en":"The old clock tower in the square still keeps perfect time.","vi":"Tháp đồng hồ cũ ở quảng trường vẫn chạy rất đúng giờ."},{"en":"Our office is in that tall glass tower downtown.","vi":"Văn phòng của chúng tôi nằm trong tòa nhà kính cao tầng ở trung tâm thành phố."}]', '[{"phrase":"clock tower"},{"phrase":"office tower"},{"phrase":"water tower"},{"phrase":"top of the tower"}]', NULL, '/ˈtaʊər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tow/tower/tower__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 25, 'characterize', 'mô tả đặc điểm; là đặc điểm của', 'verb', '[{"en":"The region is characterized by hot summers and cold winters.","vi":"Vùng này có đặc điểm là mùa hè nóng và mùa đông lạnh."},{"en":"His paintings are characterized by bright colors.","vi":"Tranh của anh ấy có đặc điểm là màu sắc tươi sáng."},{"en":"How would you characterize your relationship with your boss?","vi":"Bạn sẽ mô tả mối quan hệ giữa bạn và sếp như thế nào?"}]', '[{"phrase":"be characterized by"},{"phrase":"characterize as"},{"phrase":"generally characterized"}]', 'be characterized by: có đặc điểm là · Anh: characterise', '/ˈkærəktəraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/characterize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 26, 'specify', 'ghi rõ; nêu cụ thể', 'verb', '[{"en":"Please specify your size when you order the shirt.","vi":"Vui lòng ghi rõ cỡ áo khi bạn đặt mua."},{"en":"The rules do not specify how long the break should be.","vi":"Quy định không nêu rõ giờ nghỉ nên kéo dài bao lâu."},{"en":"Unless otherwise specified, all prices include tax.","vi":"Trừ khi có ghi chú khác, tất cả giá đều đã bao gồm thuế."}]', '[{"phrase":"clearly specify"},{"phrase":"unless otherwise specified"},{"phrase":"specify the size"}]', NULL, '/ˈspesɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 27, 'exact', 'chính xác; đúng; giống hệt', 'adjective', '[{"en":"What is the exact time of your flight?","vi":"Giờ bay chính xác của bạn là mấy giờ?"},{"en":"I can''t remember the exact words she used.","vi":"Tôi không nhớ chính xác những từ cô ấy đã dùng."},{"en":"The twins wore the exact same dress to the party.","vi":"Hai chị em sinh đôi mặc chiếc váy giống hệt nhau đến bữa tiệc."}]', '[{"phrase":"exact time"},{"phrase":"exact words"},{"phrase":"exact same"},{"phrase":"exact amount"}]', NULL, '/ɪɡˈzækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exact/exact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 28, 'spin', 'quay tròn; quay cuồng', 'verb', '[{"en":"The children spun around until they felt dizzy.","vi":"Bọn trẻ quay vòng vòng cho đến khi thấy chóng mặt."},{"en":"The wheels kept spinning in the deep mud.","vi":"Bánh xe cứ quay tít trong bùn sâu."},{"en":"My head is spinning after that long meeting.","vi":"Đầu tôi quay cuồng sau cuộc họp dài đó."}]', '[{"phrase":"spin around"},{"phrase":"head is spinning"},{"phrase":"spin the wheel"}]', 'spin – spun – spun', '/spɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spi/spin_/spin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 29, 'operator', 'người vận hành; tổng đài viên; công ty điều hành', 'noun', '[{"en":"The operator put my call through to the right department.","vi":"Tổng đài viên đã nối máy cho tôi đến đúng phòng ban."},{"en":"He works as a machine operator in a factory.","vi":"Anh ấy làm công nhân vận hành máy trong một nhà máy."},{"en":"We booked our trip through a local tour operator.","vi":"Chúng tôi đặt chuyến đi qua một công ty du lịch địa phương."}]', '[{"phrase":"tour operator"},{"phrase":"machine operator"},{"phrase":"telephone operator"}]', NULL, '/ˈɑːpəreɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operator__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-11', 30, 'infant', 'trẻ sơ sinh; em bé', 'noun', '[{"en":"The nurse showed us how to hold an infant safely.","vi":"Y tá hướng dẫn chúng tôi cách bế trẻ sơ sinh an toàn."},{"en":"This car seat is designed for infants under one year old.","vi":"Ghế ô tô này được thiết kế cho em bé dưới một tuổi."},{"en":"She has a lot of experience caring for infants.","vi":"Cô ấy có nhiều kinh nghiệm chăm sóc trẻ sơ sinh."}]', '[{"phrase":"newborn infant"},{"phrase":"infant care"},{"phrase":"young infant"}]', NULL, '/ˈɪnfənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infan/infant__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-12', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 12', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 12);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 1, 'dig', 'đào; bới', 'verb', '[{"en":"The kids spent all afternoon digging holes in the sand.","vi":"Bọn trẻ dành cả buổi chiều đào hố trên cát."},{"en":"We need to dig a small hole for this tree.","vi":"Chúng ta cần đào một cái hố nhỏ để trồng cây này."},{"en":"Our dog dug up all the flowers in the garden again.","vi":"Con chó nhà tôi lại bới hết hoa trong vườn lên."}]', '[{"phrase":"dig a hole"},{"phrase":"dig up"},{"phrase":"dig deep"}]', 'dig – dug – dug', '/dɪɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dig/dig__/dig__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 2, 'drag', 'kéo lê; lôi; kéo (chuột)', 'verb', '[{"en":"He dragged his heavy suitcase up the stairs to his room.","vi":"Anh ấy kéo lê chiếc vali nặng lên cầu thang về phòng."},{"en":"My friends dragged me to a party I didn''t want to attend.","vi":"Bạn bè lôi tôi đến một bữa tiệc mà tôi không muốn đi."},{"en":"Just drag the file into this folder and drop it.","vi":"Bạn chỉ cần kéo tệp vào thư mục này rồi thả ra."}]', '[{"phrase":"drag and drop"},{"phrase":"drag a chair"},{"phrase":"drag a suitcase"}]', NULL, '/dræɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drag_/drag__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 3, 'mount', 'tăng dần; gắn (lên tường); lên (ngựa, xe)', 'verb', '[{"en":"Pressure is mounting on the team to finish the project.","vi":"Áp lực đối với nhóm để hoàn thành dự án đang tăng dần."},{"en":"We mounted the TV on the wall above the fireplace.","vi":"Chúng tôi gắn tivi lên tường phía trên lò sưởi."},{"en":"She mounted her bike and rode off down the street.","vi":"Cô ấy lên xe đạp rồi đạp đi dọc con phố."}]', '[{"phrase":"mounting pressure"},{"phrase":"mount a TV"},{"phrase":"mount a bike"}]', NULL, '/maʊnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mount/mount__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 4, 'wrap', 'gói; quấn', 'verb', '[{"en":"I still need to wrap the presents before the party tonight.","vi":"Tôi vẫn cần gói quà trước bữa tiệc tối nay."},{"en":"She wrapped a warm scarf around her neck and went outside.","vi":"Cô ấy quấn một chiếc khăn ấm quanh cổ rồi ra ngoài."},{"en":"Wrap the sandwiches in paper so they stay fresh.","vi":"Hãy gói bánh mì kẹp trong giấy để chúng luôn tươi."}]', '[{"phrase":"wrap a present"},{"phrase":"wrap something in paper"},{"phrase":"wrap up"}]', NULL, '/ræp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wra/wrap_/wrap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 5, 'anticipate', 'lường trước; dự đoán', 'verb', '[{"en":"We didn''t anticipate so many people coming to the event.","vi":"Chúng tôi không lường trước có nhiều người đến sự kiện như vậy."},{"en":"Good teachers anticipate the questions their students might ask.","vi":"Giáo viên giỏi lường trước những câu hỏi học sinh có thể đặt ra."},{"en":"The trip took longer than we had anticipated.","vi":"Chuyến đi mất nhiều thời gian hơn chúng tôi đã dự đoán."}]', '[{"phrase":"anticipate problems"},{"phrase":"than anticipated"},{"phrase":"anticipate demand"}]', NULL, '/ænˈtɪsɪpeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ant/antic/anticipate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 6, 'dependent', 'phụ thuộc; lệ thuộc', 'adjective', '[{"en":"Many students are still financially dependent on their parents.","vi":"Nhiều sinh viên vẫn còn phụ thuộc vào bố mẹ về tài chính."},{"en":"The town''s economy is heavily dependent on tourism.","vi":"Nền kinh tế của thị trấn phụ thuộc nhiều vào du lịch."},{"en":"Try not to become too dependent on your phone.","vi":"Cố gắng đừng quá lệ thuộc vào điện thoại của bạn."}]', '[{"phrase":"dependent on"},{"phrase":"heavily dependent"},{"phrase":"financially dependent"}]', 'dependent on (sth) · trái nghĩa: independent', '/dɪˈpendənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depen/dependent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 7, 'specialize', 'chuyên về; chuyên sâu', 'verb', '[{"en":"This restaurant specializes in fresh seafood from the coast.","vi":"Nhà hàng này chuyên về hải sản tươi từ vùng biển."},{"en":"She wants to specialize in children''s health after medical school.","vi":"Cô ấy muốn chuyên sâu về sức khỏe trẻ em sau khi học xong trường y."},{"en":"My uncle is a lawyer who specializes in family law.","vi":"Chú tôi là luật sư chuyên về luật gia đình."}]', '[{"phrase":"specialize in"},{"phrase":"highly specialized"}]', 'specialize in · Mỹ: specialize · Anh: specialise', '/ˈspeʃəlaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specialize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 8, 'angle', 'góc; góc độ', 'noun', '[{"en":"Take the photo from a different angle to get better light.","vi":"Hãy chụp ảnh từ một góc khác để có ánh sáng đẹp hơn."},{"en":"The ladder was leaning against the wall at a steep angle.","vi":"Chiếc thang dựa vào tường ở một góc rất dốc."},{"en":"Let''s look at this problem from a new angle.","vi":"Chúng ta hãy nhìn vấn đề này từ một góc độ mới."}]', '[{"phrase":"from a different angle"},{"phrase":"at an angle"},{"phrase":"camera angle"}]', NULL, '/ˈæŋɡl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/angle/angle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 9, 'chicken', 'gà; thịt gà', 'noun', '[{"en":"My grandmother keeps a few chickens in her backyard.","vi":"Bà tôi nuôi vài con gà ở sân sau."},{"en":"We''re having grilled chicken and rice for dinner tonight.","vi":"Tối nay chúng ta ăn gà nướng và cơm."},{"en":"Could you buy some chicken on your way home?","vi":"Bạn có thể mua ít thịt gà trên đường về nhà không?"}]', '[{"phrase":"fried chicken"},{"phrase":"chicken soup"},{"phrase":"roast chicken"}]', 'thịt gà: không đếm được (some chicken)', '/ˈtʃɪkɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chick/chicken__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 10, 'anxiety', 'sự lo lắng; sự lo âu', 'noun', '[{"en":"Many students feel a lot of anxiety before their exams.","vi":"Nhiều học sinh cảm thấy rất lo lắng trước kỳ thi."},{"en":"Regular exercise can help reduce stress and anxiety.","vi":"Tập thể dục đều đặn có thể giúp giảm căng thẳng và lo âu."},{"en":"She hid her anxiety and smiled at the interviewer.","vi":"Cô ấy giấu đi sự lo lắng và mỉm cười với người phỏng vấn."}]', '[{"phrase":"feel anxiety"},{"phrase":"reduce anxiety"},{"phrase":"stress and anxiety"}]', 'tính từ: anxious', '/æŋˈzaɪəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anx/anxie/anxiety__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 11, 'virus', 'vi-rút; vi-rút máy tính', 'noun', '[{"en":"The doctor said my cold was caused by a virus.","vi":"Bác sĩ nói bệnh cảm của tôi là do một loại vi-rút gây ra."},{"en":"Wash your hands often to stop the virus from spreading.","vi":"Hãy rửa tay thường xuyên để ngăn vi-rút lây lan."},{"en":"Don''t open that email, because it might contain a virus.","vi":"Đừng mở email đó, vì nó có thể chứa vi-rút."}]', '[{"phrase":"catch a virus"},{"phrase":"the virus spreads"},{"phrase":"computer virus"}]', 'số nhiều: viruses', '/ˈvaɪrəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virus/virus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 12, 'precisely', 'chính xác; đúng', 'adverb', '[{"en":"The train left at precisely nine o''clock this morning.","vi":"Tàu rời ga lúc đúng chín giờ sáng nay."},{"en":"It''s hard to say precisely how many people came.","vi":"Thật khó nói chính xác có bao nhiêu người đã đến."},{"en":"That is precisely the reason I wanted to talk to you.","vi":"Đó chính là lý do tôi muốn nói chuyện với bạn."}]', '[{"phrase":"precisely because"},{"phrase":"at precisely"},{"phrase":"know precisely"}]', NULL, '/prɪˈsaɪsli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precisely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 13, 'rival', 'đối thủ; đối thủ cạnh tranh', 'noun', '[{"en":"Our team finally beat our biggest rival last weekend.","vi":"Cuối tuần trước đội chúng tôi cuối cùng đã đánh bại đối thủ lớn nhất."},{"en":"The two companies have been rivals for many years.","vi":"Hai công ty đó đã là đối thủ cạnh tranh trong nhiều năm."},{"en":"She works harder than any of her rivals at school.","vi":"Cô ấy chăm chỉ hơn bất kỳ đối thủ nào của mình ở trường."}]', '[{"phrase":"main rival"},{"phrase":"close rival"},{"phrase":"rival team"}]', NULL, '/ˈraɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/riv/rival/rival__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 14, 'offense', 'tội; sự xúc phạm', 'noun', '[{"en":"Driving without a license is a serious offense in most countries.","vi":"Lái xe không có bằng là một tội nghiêm trọng ở hầu hết các nước."},{"en":"It was his first offense, so he only paid a fine.","vi":"Đó là lần phạm tội đầu tiên của anh ấy nên anh ấy chỉ bị phạt tiền."},{"en":"No offense, but I don''t really like your new haircut.","vi":"Không có ý xúc phạm đâu, nhưng tôi không thích kiểu tóc mới của bạn lắm."}]', '[{"phrase":"serious offense"},{"phrase":"commit an offense"},{"phrase":"take offense"},{"phrase":"no offense"}]', 'Mỹ: offense · Anh: offence', '/əˈfens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offen/offense__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 15, 'detect', 'phát hiện; nhận ra', 'verb', '[{"en":"This test can detect the disease at a very early stage.","vi":"Xét nghiệm này có thể phát hiện bệnh ở giai đoạn rất sớm."},{"en":"The alarm goes off when it detects smoke in the kitchen.","vi":"Chuông báo kêu khi phát hiện có khói trong bếp."},{"en":"I detected a hint of worry in her voice.","vi":"Tôi nhận ra một chút lo lắng trong giọng nói của cô ấy."}]', '[{"phrase":"detect smoke"},{"phrase":"detect a problem"},{"phrase":"difficult to detect"}]', NULL, '/dɪˈtekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detec/detect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 16, 'teenager', 'thanh thiếu niên; tuổi mới lớn', 'noun', '[{"en":"Most teenagers spend several hours a day on their phones.","vi":"Hầu hết thanh thiếu niên dành vài giờ mỗi ngày cho điện thoại."},{"en":"When I was a teenager, I worked in a café every summer.","vi":"Hồi tuổi mới lớn, mùa hè nào tôi cũng làm ở một quán cà phê."},{"en":"Their two teenagers help a lot with the housework.","vi":"Hai đứa con tuổi mới lớn của họ giúp việc nhà rất nhiều."}]', '[{"phrase":"young teenager"},{"phrase":"as a teenager"},{"phrase":"typical teenager"}]', 'tuổi 13–19', '/ˈtiːneɪdʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tee/teena/teenager__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 17, 'admire', 'ngưỡng mộ; chiêm ngưỡng', 'verb', '[{"en":"I really admire people who can speak several languages.","vi":"Tôi thực sự ngưỡng mộ những người nói được nhiều thứ tiếng."},{"en":"We stopped on the bridge to admire the view.","vi":"Chúng tôi dừng lại trên cầu để chiêm ngưỡng quang cảnh."},{"en":"She has always admired her mother for her courage.","vi":"Cô ấy luôn ngưỡng mộ mẹ mình vì lòng dũng cảm của bà."}]', '[{"phrase":"admire the view"},{"phrase":"admire someone for"},{"phrase":"greatly admire"}]', 'admire sb for sth', '/ədˈmaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admir/admire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 18, 'moderate', 'vừa phải; ôn hòa', 'adjective', '[{"en":"Doctors recommend at least thirty minutes of moderate exercise a day.","vi":"Bác sĩ khuyên nên tập thể dục vừa phải ít nhất ba mươi phút mỗi ngày."},{"en":"Drinking moderate amounts of coffee is usually fine for most adults.","vi":"Uống cà phê ở mức vừa phải thường không sao đối với hầu hết người lớn."},{"en":"He has fairly moderate views and rarely argues with anyone.","vi":"Anh ấy có quan điểm khá ôn hòa và hiếm khi tranh cãi với ai."}]', '[{"phrase":"moderate exercise"},{"phrase":"moderate amounts"},{"phrase":"moderate views"}]', NULL, '/ˈmɑːdərət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/moder/moderate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 19, 'surgery', 'phẫu thuật; ca mổ', 'noun', '[{"en":"My dad had knee surgery last month and is recovering well.","vi":"Bố tôi đã phẫu thuật đầu gối tháng trước và đang hồi phục tốt."},{"en":"The surgery on her back took about three hours.","vi":"Ca mổ lưng của cô ấy kéo dài khoảng ba tiếng."},{"en":"She will need surgery to fix her broken arm.","vi":"Cô ấy sẽ cần phẫu thuật để chữa cánh tay bị gãy."}]', '[{"phrase":"have surgery"},{"phrase":"undergo surgery"},{"phrase":"knee surgery"},{"phrase":"need surgery"}]', NULL, '/ˈsɜːrdʒəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surge/surgery__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 20, 'musician', 'nhạc sĩ; nhạc công', 'noun', '[{"en":"A local musician played the guitar at our wedding.","vi":"Một nhạc công địa phương đã chơi ghi-ta ở đám cưới của chúng tôi."},{"en":"My brother wants to become a professional musician one day.","vi":"Anh trai tôi muốn một ngày nào đó trở thành nhạc sĩ chuyên nghiệp."},{"en":"Street musicians often perform in the park on Sundays.","vi":"Các nhạc công đường phố thường biểu diễn trong công viên vào Chủ nhật."}]', '[{"phrase":"professional musician"},{"phrase":"talented musician"},{"phrase":"street musician"}]', NULL, '/mjuˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/musician__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 21, 'significance', 'tầm quan trọng; ý nghĩa', 'noun', '[{"en":"At the time, nobody understood the significance of his discovery.","vi":"Vào lúc đó, không ai hiểu được tầm quan trọng của phát hiện của anh ấy."},{"en":"This old temple has great historical significance for the town.","vi":"Ngôi đền cổ này có ý nghĩa lịch sử to lớn đối với thị trấn."},{"en":"The color red has a special significance in many cultures.","vi":"Màu đỏ có ý nghĩa đặc biệt trong nhiều nền văn hóa."}]', '[{"phrase":"historical significance"},{"phrase":"great significance"},{"phrase":"understand the significance"}]', 'tính từ: significant', '/sɪɡˈnɪfɪkəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 22, 'shower', 'vòi sen; việc tắm vòi sen; mưa rào', 'noun', '[{"en":"I always take a quick shower after going to the gym.","vi":"Tôi luôn tắm nhanh bằng vòi sen sau khi đi tập gym."},{"en":"The shower in our hotel room didn''t have any hot water.","vi":"Vòi sen trong phòng khách sạn của chúng tôi không có nước nóng."},{"en":"There will be a few light showers this afternoon.","vi":"Chiều nay sẽ có vài cơn mưa rào nhẹ."}]', '[{"phrase":"take a shower"},{"phrase":"hot shower"},{"phrase":"light showers"}]', NULL, '/ˈʃaʊər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/showe/shower__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 23, 'illegal', 'bất hợp pháp; trái phép', 'adjective', '[{"en":"It is illegal to park your car in front of a hospital entrance.","vi":"Đỗ xe trước lối vào bệnh viện là bất hợp pháp."},{"en":"The police found illegal copies of movies in the shop.","vi":"Cảnh sát tìm thấy các bản sao phim trái phép trong cửa hàng."},{"en":"Selling alcohol to children is illegal in this country.","vi":"Bán rượu cho trẻ em là bất hợp pháp ở nước này."}]', '[{"phrase":"it is illegal to"},{"phrase":"illegal parking"},{"phrase":"illegal activity"}]', 'trái nghĩa: legal', '/ɪˈliːɡl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illeg/illegal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 24, 'charity', 'tổ chức từ thiện; việc từ thiện', 'noun', '[{"en":"She works for a charity that helps homeless animals.","vi":"Cô ấy làm việc cho một tổ chức từ thiện giúp đỡ động vật vô gia cư."},{"en":"We gave all our old clothes to charity last week.","vi":"Tuần trước chúng tôi đã đem hết quần áo cũ đi làm từ thiện."},{"en":"The school is organizing a charity run next Saturday.","vi":"Trường đang tổ chức một cuộc chạy từ thiện vào thứ Bảy tới."}]', '[{"phrase":"give to charity"},{"phrase":"charity event"},{"phrase":"local charity"},{"phrase":"raise money for charity"}]', NULL, '/ˈtʃærəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chari/charity__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 25, 'universal', 'phổ biến; phổ quát; chung cho mọi người', 'adjective', '[{"en":"Music is a universal language that everyone can enjoy.","vi":"Âm nhạc là ngôn ngữ chung mà ai cũng có thể thưởng thức."},{"en":"The new plan received almost universal support from the staff.","vi":"Kế hoạch mới nhận được sự ủng hộ gần như từ tất cả nhân viên."},{"en":"The desire to be happy is universal.","vi":"Mong muốn được hạnh phúc là điều phổ quát ở mọi người."}]', '[{"phrase":"universal language"},{"phrase":"universal appeal"},{"phrase":"universal support"}]', NULL, '/ˌjuːnɪˈvɜːrsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/universal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 26, 'cigarette', 'điếu thuốc lá; thuốc lá', 'noun', '[{"en":"My uncle finally stopped smoking cigarettes after twenty years.","vi":"Chú tôi cuối cùng đã bỏ hút thuốc lá sau hai mươi năm."},{"en":"Please don''t throw your cigarette on the beach.","vi":"Làm ơn đừng vứt điếu thuốc trên bãi biển."},{"en":"The price of cigarettes has gone up again this year.","vi":"Giá thuốc lá lại tăng trong năm nay."}]', '[{"phrase":"smoke a cigarette"},{"phrase":"light a cigarette"},{"phrase":"packet of cigarettes"}]', NULL, '/ˈsɪɡəret/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cig/cigar/cigarette__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 27, 'constitute', 'cấu thành; chiếm; được coi là', 'verb', '[{"en":"Women constitute more than half of the company''s workforce.","vi":"Phụ nữ chiếm hơn một nửa lực lượng lao động của công ty."},{"en":"Twelve short chapters constitute the first part of the book.","vi":"Mười hai chương ngắn tạo thành phần đầu của cuốn sách."},{"en":"Being late once does not constitute a serious problem.","vi":"Đi muộn một lần không được coi là vấn đề nghiêm trọng."}]', '[{"phrase":"constitute a threat"},{"phrase":"constitute a problem"},{"phrase":"constitute a majority"}]', NULL, '/ˈkɑːnstɪtuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstitute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 28, 'adequate', 'đủ; thỏa đáng', 'adjective', '[{"en":"Make sure you get adequate sleep before the big exam.","vi":"Hãy chắc chắn rằng bạn ngủ đủ giấc trước kỳ thi quan trọng."},{"en":"The room was small but perfectly adequate for two people.","vi":"Căn phòng nhỏ nhưng hoàn toàn đủ cho hai người."},{"en":"He couldn''t give an adequate explanation for his mistake.","vi":"Anh ấy không thể đưa ra lời giải thích thỏa đáng cho sai lầm của mình."}]', '[{"phrase":"adequate sleep"},{"phrase":"adequate explanation"},{"phrase":"perfectly adequate"}]', 'trái nghĩa: inadequate', '/ˈædɪkwət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ade/adequ/adequate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 29, 'consultant', 'chuyên gia tư vấn; cố vấn', 'noun', '[{"en":"The company hired a consultant to improve its sales.","vi":"Công ty đã thuê một chuyên gia tư vấn để cải thiện doanh số."},{"en":"My sister works as a marketing consultant for small businesses.","vi":"Chị gái tôi làm cố vấn tiếp thị cho các doanh nghiệp nhỏ."},{"en":"We should ask a financial consultant before buying the house.","vi":"Chúng ta nên hỏi ý kiến một chuyên gia tư vấn tài chính trước khi mua nhà."}]', '[{"phrase":"hire a consultant"},{"phrase":"financial consultant"},{"phrase":"management consultant"}]', NULL, '/kənˈsʌltənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsultant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-12', 30, 'historian', 'nhà sử học', 'noun', '[{"en":"Historians still disagree about when the old city was built.","vi":"Các nhà sử học vẫn chưa thống nhất về thời điểm thành phố cổ được xây dựng."},{"en":"A local historian gave us a tour of the castle.","vi":"Một nhà sử học địa phương đã dẫn chúng tôi tham quan lâu đài."},{"en":"She studied for many years to become a historian.","vi":"Cô ấy đã học nhiều năm để trở thành nhà sử học."}]', '[{"phrase":"art historian"},{"phrase":"local historian"},{"phrase":"historians believe"}]', NULL, '/hɪˈstɔːriən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historian__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-13', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 13', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 13);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 1, 'cousin', 'anh chị em họ', 'noun', '[{"en":"My cousin is getting married in Hanoi next month.","vi":"Anh họ tôi sẽ cưới vợ ở Hà Nội vào tháng sau."},{"en":"We stayed with our cousins over summer vacation.","vi":"Chúng tôi ở nhà anh chị em họ trong kỳ nghỉ hè."},{"en":"He is a distant cousin on my mother''s side.","vi":"Anh ấy là anh họ xa bên ngoại của tôi."}]', '[{"phrase":"first cousin"},{"phrase":"distant cousin"},{"phrase":"older cousin"}]', NULL, '/ˈkʌzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cousi/cousin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 2, 'visual', 'thuộc thị giác; trực quan; hình ảnh', 'adjective', '[{"en":"Children often learn better with visual aids like pictures.","vi":"Trẻ em thường học tốt hơn với đồ dùng trực quan như tranh ảnh."},{"en":"The movie has amazing visual effects but a weak story.","vi":"Bộ phim có kỹ xảo hình ảnh tuyệt vời nhưng cốt truyện yếu."},{"en":"Some people have a very good visual memory for faces.","vi":"Một số người có trí nhớ hình ảnh rất tốt đối với khuôn mặt."}]', '[{"phrase":"visual aids"},{"phrase":"visual effects"},{"phrase":"visual memory"},{"phrase":"visual arts"}]', NULL, '/ˈvɪʒuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visua/visual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 3, 'stupid', 'ngu ngốc; ngớ ngẩn', 'adjective', '[{"en":"I made a stupid mistake on my math test.","vi":"Tôi đã mắc một lỗi ngớ ngẩn trong bài kiểm tra toán."},{"en":"It was stupid of me to leave my keys in the car.","vi":"Tôi thật ngốc khi để quên chìa khóa trong xe."},{"en":"There''s no such thing as a stupid question in this class.","vi":"Trong lớp này không có câu hỏi nào là ngớ ngẩn cả."}]', '[{"phrase":"stupid mistake"},{"phrase":"stupid question"},{"phrase":"feel stupid"}]', NULL, '/ˈstuːpɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stupi/stupid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 4, 'keen', 'háo hức; say mê; nhạy bén', 'adjective', '[{"en":"She is very keen on learning Japanese.","vi":"Cô ấy rất say mê học tiếng Nhật."},{"en":"The new staff are keen to learn and ask lots of questions.","vi":"Các nhân viên mới rất háo hức học hỏi và đặt nhiều câu hỏi."},{"en":"Dogs have a very keen sense of smell.","vi":"Chó có khứu giác rất nhạy bén."}]', '[{"phrase":"keen on"},{"phrase":"keen to learn"},{"phrase":"keen interest"},{"phrase":"keen sense of smell"}]', 'keen on + N/V-ing: thích, say mê', '/kiːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kee/keen_/keen__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 5, 'ethnic', 'thuộc dân tộc; sắc tộc', 'adjective', '[{"en":"Vietnam has fifty-four officially recognized ethnic groups.","vi":"Việt Nam có 54 dân tộc được công nhận chính thức."},{"en":"The museum displays traditional clothes from many ethnic minorities.","vi":"Bảo tàng trưng bày trang phục truyền thống của nhiều dân tộc thiểu số."},{"en":"Students from different ethnic backgrounds study together at this school.","vi":"Học sinh thuộc nhiều dân tộc khác nhau cùng học ở trường này."}]', '[{"phrase":"ethnic group"},{"phrase":"ethnic minority"},{"phrase":"ethnic background"}]', NULL, '/ˈeθnɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethni/ethnic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 6, 'twin', 'trẻ sinh đôi; song sinh', 'noun', '[{"en":"My sister just gave birth to twins.","vi":"Chị tôi vừa sinh đôi."},{"en":"Even their parents can''t tell the twins apart.","vi":"Ngay cả bố mẹ cũng không phân biệt được hai đứa sinh đôi."},{"en":"He has a twin brother who lives in Australia.","vi":"Anh ấy có một người anh em song sinh sống ở Úc."}]', '[{"phrase":"twin brother"},{"phrase":"twin sister"},{"phrase":"identical twins"}]', NULL, '/twɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twin_/twin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 7, 'clinical', 'lâm sàng', 'adjective', '[{"en":"The new drug is still in clinical trials.","vi":"Loại thuốc mới vẫn đang được thử nghiệm lâm sàng."},{"en":"Medical students gain clinical experience by working in hospitals.","vi":"Sinh viên y tích lũy kinh nghiệm lâm sàng bằng cách làm việc ở bệnh viện."},{"en":"She works as a clinical psychologist at a children''s hospital.","vi":"Cô ấy là nhà tâm lý học lâm sàng tại một bệnh viện nhi."}]', '[{"phrase":"clinical trial"},{"phrase":"clinical experience"},{"phrase":"clinical practice"}]', NULL, '/ˈklɪnɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/clini/clinical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 8, 'eastern', '(thuộc) phía đông; phương Đông', 'adjective', '[{"en":"Heavy rain is expected in eastern parts of the country.","vi":"Dự kiến sẽ có mưa lớn ở các vùng phía đông của đất nước."},{"en":"They spent two weeks traveling around Eastern Europe.","vi":"Họ đã dành hai tuần đi du lịch vòng quanh Đông Âu."},{"en":"Many Western visitors are interested in Eastern culture and food.","vi":"Nhiều du khách phương Tây quan tâm đến văn hóa và ẩm thực phương Đông."}]', '[{"phrase":"eastern part"},{"phrase":"Eastern Europe"},{"phrase":"eastern coast"}]', NULL, '/ˈiːstərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easte/eastern__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 9, 'forecast', 'dự báo', 'noun', '[{"en":"The weather forecast says it will rain this afternoon.","vi":"Dự báo thời tiết nói chiều nay trời sẽ mưa."},{"en":"Did you check the forecast before planning the picnic?","vi":"Bạn đã xem dự báo trước khi lên kế hoạch đi dã ngoại chưa?"},{"en":"The company''s sales forecast for next year looks very positive.","vi":"Dự báo doanh số năm tới của công ty trông rất khả quan."}]', '[{"phrase":"weather forecast"},{"phrase":"sales forecast"},{"phrase":"economic forecast"}]', 'động từ: forecast – forecast – forecast', '/ˈfɔːrkæst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forec/forecast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 10, 'segment', 'phần; đoạn; phân khúc', 'noun', '[{"en":"Peel the orange and divide it into segments.","vi":"Bóc vỏ quả cam rồi tách thành từng múi."},{"en":"The show''s final segment is about healthy cooking.","vi":"Phần cuối của chương trình nói về cách nấu ăn lành mạnh."},{"en":"Young people are the fastest-growing segment of the market.","vi":"Giới trẻ là phân khúc tăng trưởng nhanh nhất của thị trường."}]', '[{"phrase":"market segment"},{"phrase":"small segment"},{"phrase":"divide into segments"}]', NULL, '/ˈseɡmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seg/segme/segment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 11, 'custom', 'phong tục; tập quán', 'noun', '[{"en":"It is the custom in Vietnam to give children lucky money at Tet.","vi":"Ở Việt Nam có phong tục lì xì cho trẻ em vào dịp Tết."},{"en":"Visitors should learn about local customs before traveling abroad.","vi":"Du khách nên tìm hiểu phong tục địa phương trước khi ra nước ngoài."},{"en":"Taking off your shoes before entering a home is an old custom.","vi":"Cởi giày trước khi vào nhà là một phong tục lâu đời."}]', '[{"phrase":"local customs"},{"phrase":"old custom"},{"phrase":"follow a custom"}]', 'customs (số nhiều) còn có nghĩa: hải quan', '/ˈkʌstəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cus/custo/custom__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 12, 'adapt', 'thích nghi; điều chỉnh; chuyển thể', 'verb', '[{"en":"It took me months to adapt to life in a new country.","vi":"Tôi mất nhiều tháng để thích nghi với cuộc sống ở một đất nước mới."},{"en":"Teachers often adapt their lessons for students with different needs.","vi":"Giáo viên thường điều chỉnh bài giảng cho học sinh có nhu cầu khác nhau."},{"en":"The novel was adapted into a popular TV series.","vi":"Cuốn tiểu thuyết đã được chuyển thể thành một bộ phim truyền hình ăn khách."}]', '[{"phrase":"adapt to change"},{"phrase":"adapt quickly"},{"phrase":"adapted from a novel"}]', 'adapt (thích nghi) ≠ adopt (nhận nuôi; áp dụng)', '/əˈdæpt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ada/adapt/adapt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 13, 'sand', 'cát', 'noun', '[{"en":"The children spent all afternoon building castles in the sand.","vi":"Bọn trẻ dành cả buổi chiều xây lâu đài trên cát."},{"en":"The sand gets very hot at noon, so wear sandals.","vi":"Cát rất nóng vào buổi trưa, nên hãy đi dép."},{"en":"I still have sand in my shoes from the beach.","vi":"Giày tôi vẫn còn cát từ bãi biển."}]', '[{"phrase":"white sand"},{"phrase":"soft sand"},{"phrase":"grain of sand"}]', 'không đếm được', '/sænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/san/sand_/sand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 14, 'cap', 'mũ lưỡi trai; nắp', 'noun', '[{"en":"He always wears a baseball cap when he goes running.","vi":"Anh ấy luôn đội mũ lưỡi trai khi đi chạy bộ."},{"en":"Please put the cap back on the pen when you''re done.","vi":"Dùng xong thì bạn nhớ đậy nắp bút lại nhé."},{"en":"I can''t open this bottle because the cap is too tight.","vi":"Tôi không mở được chai này vì nắp chặt quá."}]', '[{"phrase":"baseball cap"},{"phrase":"bottle cap"},{"phrase":"wear a cap"}]', NULL, '/kæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/cap__/cap__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 15, 'prompt', 'thúc đẩy; khiến; nhắc', 'verb', '[{"en":"Rising prices prompted many families to cook at home more.","vi":"Giá cả tăng khiến nhiều gia đình nấu ăn ở nhà nhiều hơn."},{"en":"What prompted you to change your career?","vi":"Điều gì đã thúc đẩy bạn thay đổi nghề nghiệp?"},{"en":"The app will prompt you to enter your password again.","vi":"Ứng dụng sẽ nhắc bạn nhập lại mật khẩu."}]', '[{"phrase":"prompt a response"},{"phrase":"prompt concern"},{"phrase":"prompted by"}]', 'tính từ: nhanh chóng, kịp thời (a prompt reply)', '/prɑːmpt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promp/prompt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 16, 'charm', 'sức quyến rũ; nét duyên; bùa may', 'noun', '[{"en":"The old town has kept much of its original charm.","vi":"Khu phố cổ vẫn giữ được phần lớn nét duyên vốn có."},{"en":"He used all his charm to get a better price.","vi":"Anh ấy dùng hết sức quyến rũ của mình để được giá tốt hơn."},{"en":"She wears a small silver charm for good luck.","vi":"Cô ấy đeo một chiếc bùa nhỏ bằng bạc để cầu may."}]', '[{"phrase":"lucky charm"},{"phrase":"natural charm"},{"phrase":"lose its charm"},{"phrase":"full of charm"}]', NULL, '/tʃɑːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/charm/charm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 17, 'react', 'phản ứng', 'verb', '[{"en":"How did your parents react when you told them?","vi":"Bố mẹ bạn đã phản ứng thế nào khi bạn nói với họ?"},{"en":"Drivers need to react quickly when a child runs into the road.","vi":"Tài xế cần phản ứng nhanh khi có trẻ em chạy ra đường."},{"en":"Some people react badly to certain kinds of medicine.","vi":"Một số người phản ứng xấu với một vài loại thuốc."}]', '[{"phrase":"react to"},{"phrase":"react quickly"},{"phrase":"react badly"}]', 'react to something: phản ứng với điều gì', '/riˈækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/react__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 18, 'lecture', 'bài giảng; buổi diễn thuyết; lời răn dạy', 'noun', '[{"en":"I missed the morning lecture because my bus was late.","vi":"Tôi lỡ buổi giảng sáng vì xe buýt đến muộn."},{"en":"The professor gave an interesting lecture on climate change.","vi":"Giáo sư đã có một bài giảng thú vị về biến đổi khí hậu."},{"en":"My dad gave me a long lecture about saving money.","vi":"Bố tôi giảng cho tôi một bài dài về việc tiết kiệm tiền."}]', '[{"phrase":"give a lecture"},{"phrase":"attend a lecture"},{"phrase":"lecture hall"}]', NULL, '/ˈlektʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lec/lectu/lecture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 19, 'venture', 'dự án kinh doanh; liên doanh; việc mạo hiểm', 'noun', '[{"en":"Opening a café was her first business venture.","vi":"Mở quán cà phê là dự án kinh doanh đầu tiên của cô ấy."},{"en":"The two companies formed a joint venture to build electric cars.","vi":"Hai công ty đã lập liên doanh để sản xuất ô tô điện."},{"en":"His new venture failed after only six months.","vi":"Việc kinh doanh mới của anh ấy thất bại chỉ sau sáu tháng."}]', '[{"phrase":"business venture"},{"phrase":"joint venture"},{"phrase":"new venture"}]', NULL, '/ˈventʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ven/ventu/venture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 20, 'compound', 'hợp chất; từ ghép', 'noun', '[{"en":"Water is a compound of hydrogen and oxygen.","vi":"Nước là hợp chất của hydro và oxy."},{"en":"Scientists found a new compound that may kill harmful bacteria.","vi":"Các nhà khoa học tìm ra một hợp chất mới có thể tiêu diệt vi khuẩn có hại."},{"en":"The English word \"sunflower\" is a compound of \"sun\" and \"flower\".","vi":"Từ tiếng Anh \"sunflower\" là từ ghép của \"sun\" và \"flower\"."}]', '[{"phrase":"chemical compound"},{"phrase":"organic compound"},{"phrase":"compound word"}]', NULL, '/ˈkɑːmpaʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compound__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 21, 'rescue', 'cứu; giải cứu', 'verb', '[{"en":"Firefighters rescued two children from the burning house.","vi":"Lính cứu hỏa đã cứu hai đứa trẻ khỏi ngôi nhà đang cháy."},{"en":"The fishermen were rescued after two days at sea.","vi":"Những ngư dân đã được cứu sau hai ngày lênh đênh trên biển."},{"en":"She rescued a small dog she found on the street.","vi":"Cô ấy đã cứu một chú chó nhỏ mà cô tìm thấy ngoài đường."}]', '[{"phrase":"rescue someone from"},{"phrase":"rescue team"},{"phrase":"come to the rescue"}]', NULL, '/ˈreskjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/rescu/rescue__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 22, 'mess', 'sự bừa bộn; tình trạng rối ren', 'noun', '[{"en":"Your room is a mess, so please clean it up.","vi":"Phòng con bừa bộn quá, con dọn dẹp đi nhé."},{"en":"The kids made a huge mess in the kitchen.","vi":"Bọn trẻ bày bừa khắp nhà bếp."},{"en":"My life was a mess after I lost my job.","vi":"Cuộc sống của tôi rối tung sau khi mất việc."}]', '[{"phrase":"make a mess"},{"phrase":"clean up the mess"},{"phrase":"a complete mess"}]', NULL, '/mes/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mes/mess_/mess__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 23, 'preference', 'sự ưa thích hơn; sở thích', 'noun', '[{"en":"Do you have a preference for window or aisle seats?","vi":"Bạn thích ghế cạnh cửa sổ hay ghế cạnh lối đi hơn?"},{"en":"We can order pizza or noodles; I have no preference.","vi":"Mình có thể gọi pizza hoặc mì, món nào tôi cũng được."},{"en":"Customers'' preferences change quickly, so we update the menu often.","vi":"Sở thích của khách hàng thay đổi nhanh, nên chúng tôi thường xuyên cập nhật thực đơn."}]', '[{"phrase":"preference for"},{"phrase":"personal preference"},{"phrase":"strong preference"},{"phrase":"have a preference"}]', NULL, '/ˈprefrəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prefe/preference__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 24, 'comprehensive', 'toàn diện; đầy đủ', 'adjective', '[{"en":"This guidebook gives a comprehensive list of hotels in the city.","vi":"Cuốn sách hướng dẫn này có danh sách đầy đủ các khách sạn trong thành phố."},{"en":"The doctor ordered a comprehensive health check for my father.","vi":"Bác sĩ chỉ định khám sức khỏe toàn diện cho bố tôi."},{"en":"The report offers a comprehensive review of the city''s traffic problems.","vi":"Bản báo cáo đưa ra đánh giá toàn diện về các vấn đề giao thông của thành phố."}]', '[{"phrase":"comprehensive list"},{"phrase":"comprehensive review"},{"phrase":"comprehensive guide"}]', NULL, '/ˌkɑːmprɪˈhensɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprehensive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 25, 'incentive', 'động lực; sự khuyến khích; ưu đãi', 'noun', '[{"en":"The company offers bonuses as an incentive for hard work.","vi":"Công ty trả tiền thưởng để khuyến khích làm việc chăm chỉ."},{"en":"There is little incentive to save when interest rates are low.","vi":"Khi lãi suất thấp, người ta có ít động lực để tiết kiệm."},{"en":"Free parking is a good incentive for shoppers to visit the mall.","vi":"Bãi đỗ xe miễn phí là ưu đãi tốt để thu hút người mua sắm đến trung tâm thương mại."}]', '[{"phrase":"financial incentive"},{"phrase":"tax incentive"},{"phrase":"strong incentive"},{"phrase":"provide an incentive"}]', NULL, '/ɪnˈsentɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incen/incentive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 26, 'league', 'giải đấu; liên đoàn; đẳng cấp', 'noun', '[{"en":"Our team finished second in the league this season.","vi":"Đội chúng tôi xếp thứ hai trong giải đấu mùa này."},{"en":"He plays in a local basketball league on weekends.","vi":"Anh ấy chơi trong một giải bóng rổ địa phương vào cuối tuần."},{"en":"As a cook, she is not in the same league as her mother.","vi":"Về khoản nấu ăn, cô ấy không cùng đẳng cấp với mẹ mình."}]', '[{"phrase":"win the league"},{"phrase":"league title"},{"phrase":"in the same league"}]', NULL, '/liːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leagu/league__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 27, 'dialog', 'đoạn hội thoại; lời thoại; hộp thoại', 'noun', '[{"en":"Read the dialog aloud with your partner.","vi":"Hãy đọc to đoạn hội thoại cùng bạn của em."},{"en":"The movie has great action scenes but terrible dialog.","vi":"Bộ phim có những cảnh hành động tuyệt vời nhưng lời thoại dở tệ."},{"en":"Click \"OK\" when the dialog box appears on the screen.","vi":"Nhấn \"OK\" khi hộp thoại hiện lên trên màn hình."}]', '[{"phrase":"dialog box"},{"phrase":"dialog between"}]', 'Mỹ: dialog · Anh: dialogue', '/ˈdaɪəlɔɡ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 28, 'cream', 'kem sữa; kem bôi', 'noun', '[{"en":"Do you take cream and sugar in your coffee?","vi":"Bạn có cho kem sữa và đường vào cà phê không?"},{"en":"She served the strawberries with fresh whipped cream.","vi":"Cô ấy dọn dâu tây kèm kem tươi đánh bông."},{"en":"Apply this cream to your skin twice a day.","vi":"Thoa loại kem này lên da hai lần mỗi ngày."}]', '[{"phrase":"whipped cream"},{"phrase":"sour cream"},{"phrase":"face cream"},{"phrase":"hand cream"}]', 'ice cream = kem (để ăn)', '/kriːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/cream/cream__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 29, 'rapid', 'nhanh; nhanh chóng', 'adjective', '[{"en":"The city has seen rapid growth over the past ten years.","vi":"Thành phố đã phát triển nhanh chóng trong mười năm qua."},{"en":"Technology is changing at a rapid pace these days.","vi":"Ngày nay công nghệ đang thay đổi với tốc độ nhanh."},{"en":"The patient made a rapid recovery after the surgery.","vi":"Bệnh nhân hồi phục nhanh chóng sau ca phẫu thuật."}]', '[{"phrase":"rapid growth"},{"phrase":"rapid change"},{"phrase":"rapid pace"},{"phrase":"rapid recovery"}]', NULL, '/ˈræpɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rap/rapid/rapid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-13', 30, 'cancel', 'hủy; hủy bỏ', 'verb', '[{"en":"Our flight was canceled because of the storm.","vi":"Chuyến bay của chúng tôi bị hủy vì bão."},{"en":"I need to cancel my dentist appointment tomorrow.","vi":"Tôi cần hủy lịch hẹn với nha sĩ ngày mai."},{"en":"If you cancel within 24 hours, you''ll get a full refund.","vi":"Nếu hủy trong vòng 24 giờ, bạn sẽ được hoàn tiền đầy đủ."}]', '[{"phrase":"cancel a flight"},{"phrase":"cancel an appointment"},{"phrase":"cancel a meeting"},{"phrase":"cancel an order"}]', 'Mỹ: canceled · Anh: cancelled', '/ˈkænsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/cance/cancel__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-14', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 14', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 14);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 1, 'regret', 'hối tiếc; lấy làm tiếc', 'verb', '[{"en":"I really regret not studying harder when I was at school.","vi":"Tôi thật sự hối tiếc vì đã không học chăm hơn khi còn đi học."},{"en":"I promise you won''t regret taking this job.","vi":"Tôi hứa bạn sẽ không hối tiếc khi nhận công việc này."},{"en":"We regret to inform you that the concert has been canceled.","vi":"Chúng tôi rất tiếc phải thông báo rằng buổi hòa nhạc đã bị hủy."}]', '[{"phrase":"deeply regret"},{"phrase":"regret a decision"},{"phrase":"regret to inform"}]', 'regret + V-ing: hối tiếc đã làm · regret to + V: lấy làm tiếc phải làm', '/rɪˈɡret/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regre/regret__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 2, 'dismiss', 'gạt bỏ, bác bỏ; sa thải; cho về', 'verb', '[{"en":"She quickly dismissed the idea because it was too expensive.","vi":"Cô ấy nhanh chóng gạt bỏ ý tưởng đó vì nó quá tốn kém."},{"en":"He was dismissed from his job for being late every day.","vi":"Anh ấy bị sa thải vì ngày nào cũng đi làm muộn."},{"en":"The teacher dismissed the class ten minutes early on Friday.","vi":"Thứ Sáu, giáo viên cho cả lớp về sớm mười phút."}]', '[{"phrase":"dismiss an idea"},{"phrase":"dismiss the possibility"},{"phrase":"be dismissed from a job"}]', NULL, '/dɪsˈmɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dismi/dismiss__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 3, 'margin', 'lề (trang giấy); cách biệt, chênh lệch; biên lợi nhuận', 'noun', '[{"en":"Please write your name in the left margin of the page.","vi":"Vui lòng viết tên của bạn vào lề trái của trang giấy."},{"en":"Our team won the game by a narrow margin.","vi":"Đội chúng tôi thắng trận với cách biệt sít sao."},{"en":"The shop sells cheap goods, so its profit margins are small.","vi":"Cửa hàng bán hàng giá rẻ nên biên lợi nhuận thấp."}]', '[{"phrase":"narrow margin"},{"phrase":"wide margin"},{"phrase":"profit margin"},{"phrase":"in the margin"}]', NULL, '/ˈmɑːrdʒɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/margi/margin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 4, 'beneath', 'bên dưới, ở dưới; ẩn sau', 'preposition', '[{"en":"We found the missing keys beneath a pile of old newspapers.","vi":"Chúng tôi tìm thấy chùm chìa khóa bị mất dưới một đống báo cũ."},{"en":"The ice was thin, and we could see dark water just beneath it.","vi":"Lớp băng mỏng, và chúng tôi có thể thấy làn nước tối màu ngay bên dưới."},{"en":"Beneath her smile, she was actually very worried.","vi":"Ẩn sau nụ cười, thật ra cô ấy rất lo lắng."}]', '[{"phrase":"beneath the surface"},{"phrase":"just beneath"},{"phrase":"deep beneath"}]', NULL, '/bɪˈniːθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benea/beneath__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 5, 'opponent', 'đối thủ; người phản đối', 'noun', '[{"en":"She shook hands with her opponent before the match started.","vi":"Cô ấy bắt tay đối thủ trước khi trận đấu bắt đầu."},{"en":"He is a good chess player, but his opponent is even stronger.","vi":"Anh ấy chơi cờ vua giỏi, nhưng đối thủ của anh ấy còn mạnh hơn."},{"en":"Opponents of the new road say it will destroy the forest.","vi":"Những người phản đối con đường mới nói rằng nó sẽ phá hủy khu rừng."}]', '[{"phrase":"strong opponent"},{"phrase":"beat an opponent"},{"phrase":"face an opponent"}]', NULL, '/əˈpəʊnənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppon/opponent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 6, 'resist', 'cưỡng lại; chống lại; chịu được', 'verb', '[{"en":"I couldn''t resist eating another piece of chocolate cake.","vi":"Tôi không cưỡng lại được, lại ăn thêm một miếng bánh sô-cô-la."},{"en":"Many workers resisted the changes to their working hours.","vi":"Nhiều công nhân chống lại những thay đổi về giờ làm việc của họ."},{"en":"This jacket is designed to resist wind and rain.","vi":"Chiếc áo khoác này được thiết kế để chống gió và mưa."}]', '[{"phrase":"resist temptation"},{"phrase":"can''t resist"},{"phrase":"resist change"}]', 'resist + V-ing: cưỡng lại việc làm gì', '/rɪˈzɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resis/resist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 7, 'capability', 'khả năng, năng lực', 'noun', '[{"en":"This phone has the capability to take very clear photos at night.","vi":"Chiếc điện thoại này có khả năng chụp ảnh rất rõ vào ban đêm."},{"en":"Running a marathon is beyond my capabilities right now.","vi":"Chạy marathon hiện đang vượt quá khả năng của tôi."},{"en":"The company wants to improve its production capabilities next year.","vi":"Công ty muốn nâng cao năng lực sản xuất vào năm tới."}]', '[{"phrase":"have the capability to"},{"phrase":"beyond your capabilities"},{"phrase":"technical capability"}]', NULL, '/ˌkeɪpəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capability__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 8, 'absolute', 'tuyệt đối; hoàn toàn', 'adjective', '[{"en":"I have absolute trust in my doctor.","vi":"Tôi tin tưởng tuyệt đối vào bác sĩ của mình."},{"en":"The party was an absolute disaster from start to finish.","vi":"Bữa tiệc hoàn toàn là một thảm họa từ đầu đến cuối."},{"en":"Absolute silence is required during the exam.","vi":"Trong giờ thi phải giữ im lặng tuyệt đối."}]', '[{"phrase":"absolute silence"},{"phrase":"absolute disaster"},{"phrase":"absolute confidence"},{"phrase":"absolute truth"}]', NULL, '/ˈæbsəluːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absol/absolute__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 9, 'correspond', 'tương ứng; khớp với; trao đổi thư từ', 'verb', '[{"en":"The numbers on the map correspond to the hotels listed below.","vi":"Các con số trên bản đồ tương ứng với những khách sạn được liệt kê bên dưới."},{"en":"His story doesn''t correspond with what his sister told us.","vi":"Câu chuyện của anh ấy không khớp với những gì em gái anh ấy kể với chúng tôi."},{"en":"We corresponded by email for a year before we finally met.","vi":"Chúng tôi viết email qua lại suốt một năm trước khi cuối cùng cũng gặp nhau."}]', '[{"phrase":"correspond to"},{"phrase":"correspond with"},{"phrase":"closely correspond"}]', 'correspond to/with sth: tương ứng, khớp với cái gì', '/ˌkɔːrəˈspɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correspond__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 10, 'stroke', 'đột quỵ; nét (bút, cọ); cú đánh', 'noun', '[{"en":"My grandfather had a stroke last year, but he''s recovering well.","vi":"Ông tôi bị đột quỵ năm ngoái, nhưng ông đang hồi phục tốt."},{"en":"She painted the sky with a few quick strokes of her brush.","vi":"Cô ấy vẽ bầu trời chỉ bằng vài nét cọ nhanh."},{"en":"It took her only three strokes to get the ball into the hole.","vi":"Cô ấy chỉ mất ba cú đánh để đưa bóng vào lỗ."}]', '[{"phrase":"have a stroke"},{"phrase":"brush stroke"},{"phrase":"stroke of luck"}]', 'a stroke of luck: một dịp may bất ngờ', '/strəʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strok/stroke__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 11, 'dare', 'dám; thách', 'verb', '[{"en":"I didn''t dare tell my parents that I had failed the test.","vi":"Tôi không dám nói với bố mẹ rằng mình đã trượt bài kiểm tra."},{"en":"How dare you read my messages without asking!","vi":"Sao bạn dám đọc tin nhắn của tôi mà không hỏi!"},{"en":"My friends dared me to jump into the cold lake.","vi":"Bạn bè thách tôi nhảy xuống cái hồ lạnh."}]', '[{"phrase":"how dare you"},{"phrase":"wouldn''t dare"},{"phrase":"dare to ask"}]', 'dare (to) + V: dám làm gì · dare sb to + V: thách ai làm gì', '/der/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/dare_/dare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 12, 'barrier', 'rào chắn; rào cản', 'noun', '[{"en":"Police put up barriers to keep the crowd off the road.","vi":"Cảnh sát dựng rào chắn để đám đông không tràn xuống đường."},{"en":"The language barrier was hard for us when we first moved abroad.","vi":"Rào cản ngôn ngữ rất khó khăn với chúng tôi khi mới chuyển ra nước ngoài."},{"en":"Cost is still the main barrier to college for many families.","vi":"Chi phí vẫn là rào cản chính để vào đại học đối với nhiều gia đình."}]', '[{"phrase":"language barrier"},{"phrase":"barrier to"},{"phrase":"put up a barrier"},{"phrase":"break down barriers"}]', NULL, '/ˈbæriər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/barri/barrier__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 13, 'rid', 'loại bỏ, vứt bỏ; thoát khỏi', 'verb', '[{"en":"We need to get rid of these old clothes before we move.","vi":"Chúng ta cần bỏ bớt mấy bộ quần áo cũ này trước khi chuyển nhà."},{"en":"I just can''t get rid of this terrible headache.","vi":"Tôi không sao dứt được cơn đau đầu khủng khiếp này."},{"en":"The city is working hard to rid the streets of trash.","vi":"Thành phố đang nỗ lực dọn sạch rác trên các con phố."}]', '[{"phrase":"get rid of"},{"phrase":"be rid of"},{"phrase":"rid somebody of"}]', 'rid – rid – rid; thường gặp nhất: get rid of', '/rɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rid/rid__/rid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 14, 'divorce', 'sự ly hôn', 'noun', '[{"en":"Her parents got a divorce when she was ten.","vi":"Bố mẹ cô ấy ly hôn khi cô ấy mười tuổi."},{"en":"After the divorce, he moved to a small apartment downtown.","vi":"Sau khi ly hôn, anh ấy chuyển đến một căn hộ nhỏ ở trung tâm thành phố."},{"en":"Their marriage ended in divorce after twenty years.","vi":"Cuộc hôn nhân của họ kết thúc bằng việc ly hôn sau hai mươi năm."}]', '[{"phrase":"get a divorce"},{"phrase":"end in divorce"},{"phrase":"file for divorce"},{"phrase":"divorce rate"}]', 'Cũng là động từ: divorce sb (ly hôn với ai)', '/dɪˈvɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divor/divorce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 15, 'ruin', 'làm hỏng, phá hỏng; tàn phá', 'verb', '[{"en":"The heavy rain completely ruined our picnic in the park.","vi":"Cơn mưa lớn đã phá hỏng hoàn toàn buổi dã ngoại của chúng tôi trong công viên."},{"en":"Please don''t tell me the ending, or you''ll ruin the movie.","vi":"Làm ơn đừng kể cái kết, nếu không bạn sẽ làm hỏng bộ phim mất."},{"en":"My little brother ruined the surprise by telling Mom about the party.","vi":"Em trai tôi đã làm hỏng sự bất ngờ khi kể cho mẹ về bữa tiệc."}]', '[{"phrase":"completely ruin"},{"phrase":"ruin the surprise"},{"phrase":"ruin somebody''s day"}]', NULL, '/ˈruːɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rui/ruin_/ruin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 16, 'bury', 'chôn, chôn cất; vùi', 'verb', '[{"en":"Our dog likes to bury bones in the backyard.","vi":"Con chó nhà tôi thích chôn xương ở sân sau."},{"en":"My grandmother is buried in the small village where she was born.","vi":"Bà tôi được chôn cất ở ngôi làng nhỏ nơi bà sinh ra."},{"en":"She buried her face in her hands and started to cry.","vi":"Cô ấy vùi mặt vào hai bàn tay và bắt đầu khóc."}]', '[{"phrase":"be buried in"},{"phrase":"buried treasure"},{"phrase":"bury your face in your hands"}]', 'bury – buried – buried', '/ˈberi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/bury_/bury__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 17, 'counsel', 'tư vấn; khuyên', 'verb', '[{"en":"She counsels students who are having problems at school.","vi":"Cô ấy tư vấn cho những học sinh đang gặp khó khăn ở trường."},{"en":"Most experts counsel against buying a house in a hurry.","vi":"Hầu hết các chuyên gia khuyên không nên mua nhà một cách vội vàng."},{"en":"He has counseled many couples through difficult times.","vi":"Anh ấy đã tư vấn cho nhiều cặp vợ chồng vượt qua những giai đoạn khó khăn."}]', '[{"phrase":"counsel against"},{"phrase":"counsel patients"},{"phrase":"legal counsel"}]', 'Anh: counselled · Mỹ: counseled', '/ˈkaʊnsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/couns/counsel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 18, 'tendency', 'xu hướng, khuynh hướng; thói quen', 'noun', '[{"en":"He has a tendency to talk too much when he''s nervous.","vi":"Anh ấy có xu hướng nói quá nhiều khi lo lắng."},{"en":"There is a growing tendency for young people to live alone.","vi":"Người trẻ ngày càng có xu hướng sống một mình."},{"en":"My sister''s tendency to arrive late drives everyone crazy.","vi":"Thói quen hay đến muộn của em gái tôi khiến mọi người phát điên."}]', '[{"phrase":"have a tendency to"},{"phrase":"growing tendency"},{"phrase":"natural tendency"}]', NULL, '/ˈtendənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tende/tendency__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 19, 'frequent', 'thường xuyên', 'adjective', '[{"en":"She is a frequent visitor to our restaurant.","vi":"Cô ấy là khách thường xuyên của nhà hàng chúng tôi."},{"en":"Buses to the airport are frequent, so you won''t wait long.","vi":"Xe buýt ra sân bay chạy thường xuyên nên bạn sẽ không phải chờ lâu."},{"en":"He made frequent trips to the city for work last year.","vi":"Năm ngoái anh ấy thường xuyên lên thành phố công tác."}]', '[{"phrase":"frequent visitor"},{"phrase":"frequent trips"},{"phrase":"frequent use"}]', NULL, '/ˈfriːkwənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 20, 'motor', 'động cơ, mô-tơ', 'noun', '[{"en":"The boat has a small electric motor at the back.","vi":"Chiếc thuyền có một động cơ điện nhỏ ở phía sau."},{"en":"My washing machine stopped working because the motor burned out.","vi":"Máy giặt của tôi ngừng chạy vì mô-tơ bị cháy."},{"en":"The fan makes a strange noise, so the motor might be broken.","vi":"Cái quạt kêu lạ nên có lẽ mô-tơ bị hỏng rồi."}]', '[{"phrase":"electric motor"},{"phrase":"small motor"},{"phrase":"motor vehicle"}]', NULL, '/ˈməʊtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motor/motor__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 21, 'survival', 'sự sống sót; sự tồn tại', 'noun', '[{"en":"Water is essential for survival in the desert.","vi":"Nước rất cần thiết để sống sót trong sa mạc."},{"en":"The doctors said his chances of survival were very good.","vi":"Các bác sĩ nói cơ hội sống sót của anh ấy rất cao."},{"en":"Many small shops are fighting for survival in this economy.","vi":"Nhiều cửa hàng nhỏ đang vật lộn để tồn tại trong nền kinh tế hiện nay."}]', '[{"phrase":"chance of survival"},{"phrase":"fight for survival"},{"phrase":"survival rate"}]', NULL, '/sərˈvaɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survival__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 22, 'counter', 'quầy; mặt bàn bếp', 'noun', '[{"en":"Please pay for your items at the counter.","vi":"Vui lòng thanh toán các món hàng tại quầy."},{"en":"The woman behind the counter gave me the wrong change.","vi":"Người phụ nữ đứng sau quầy thối nhầm tiền cho tôi."},{"en":"She left her keys on the kitchen counter this morning.","vi":"Sáng nay cô ấy để quên chìa khóa trên mặt bàn bếp."}]', '[{"phrase":"behind the counter"},{"phrase":"kitchen counter"},{"phrase":"check-in counter"}]', NULL, '/ˈkaʊntər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/counter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 23, 'possess', 'sở hữu; có (phẩm chất, khả năng)', 'verb', '[{"en":"He possesses a large collection of old coins.","vi":"Ông ấy sở hữu một bộ sưu tập tiền xu cổ lớn."},{"en":"Very few people possess the ability to stay calm in an emergency.","vi":"Rất ít người có khả năng giữ bình tĩnh trong tình huống khẩn cấp."},{"en":"He sold almost everything he possessed and traveled the world.","vi":"Anh ấy bán gần như mọi thứ mình sở hữu rồi đi du lịch khắp thế giới."}]', '[{"phrase":"possess the ability"},{"phrase":"possess skills"},{"phrase":"possess a quality"}]', NULL, '/pəˈzes/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posse/possess__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 24, 'permission', 'sự cho phép', 'noun', '[{"en":"You need permission from your parents to go on the trip.","vi":"Bạn cần được bố mẹ cho phép thì mới được tham gia chuyến đi."},{"en":"Did you ask permission before you took his car?","vi":"Bạn đã xin phép trước khi lấy xe của anh ấy chưa?"},{"en":"The company gave us permission to work from home on Fridays.","vi":"Công ty cho phép chúng tôi làm việc tại nhà vào các ngày thứ Sáu."}]', '[{"phrase":"ask permission"},{"phrase":"give permission"},{"phrase":"without permission"},{"phrase":"get permission"}]', 'Không đếm được', '/pərˈmɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/permi/permission__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 25, 'valley', 'thung lũng', 'noun', '[{"en":"Their small village lies in a green valley between two mountains.","vi":"Ngôi làng nhỏ của họ nằm trong một thung lũng xanh giữa hai ngọn núi."},{"en":"From the top of the hill, we could see the whole valley.","vi":"Từ đỉnh đồi, chúng tôi có thể nhìn thấy toàn bộ thung lũng."},{"en":"A river runs through the valley and into the sea.","vi":"Một con sông chảy qua thung lũng rồi đổ ra biển."}]', '[{"phrase":"deep valley"},{"phrase":"river valley"},{"phrase":"green valley"}]', NULL, '/ˈvæli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valle/valley__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 26, 'float', 'nổi; trôi', 'verb', '[{"en":"Wood floats on water, but most stones sink.","vi":"Gỗ nổi trên mặt nước, còn phần lớn đá thì chìm."},{"en":"We watched the clouds float slowly across the sky.","vi":"Chúng tôi ngắm những đám mây trôi chầm chậm trên bầu trời."},{"en":"The kids lay on their backs and floated in the pool.","vi":"Bọn trẻ nằm ngửa và thả nổi trong hồ bơi."}]', '[{"phrase":"float on water"},{"phrase":"float away"},{"phrase":"float in the air"}]', NULL, '/fləʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/float/float__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 27, 'mad', 'tức giận; điên rồ; mê (cái gì)', 'adjective', '[{"en":"My mom will be mad at me if I come home late.","vi":"Mẹ sẽ giận tôi nếu tôi về nhà muộn."},{"en":"You must be mad to swim in the sea in winter!","vi":"Bạn chắc phải điên mới đi bơi biển vào mùa đông!"},{"en":"My little brother is mad about soccer and plays every day.","vi":"Em trai tôi mê bóng đá và ngày nào cũng chơi."}]', '[{"phrase":"mad at"},{"phrase":"mad about"},{"phrase":"go mad"},{"phrase":"drive somebody mad"}]', 'mad at sb: giận ai · mad about sth: mê cái gì', '/mæd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mad/mad__/mad__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 28, 'greatly', 'rất nhiều, rất', 'adverb', '[{"en":"Thank you for your help; it is greatly appreciated.","vi":"Cảm ơn bạn đã giúp đỡ, chúng tôi vô cùng biết ơn."},{"en":"Prices vary greatly from one shop to another.","vi":"Giá cả chênh lệch rất nhiều giữa các cửa hàng."},{"en":"Her English has improved greatly since she started working abroad.","vi":"Tiếng Anh của cô ấy đã tiến bộ rất nhiều từ khi cô ấy làm việc ở nước ngoài."}]', '[{"phrase":"greatly appreciated"},{"phrase":"vary greatly"},{"phrase":"greatly improve"},{"phrase":"greatly reduce"}]', NULL, '/ˈɡreɪtli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/great/greatly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 29, 'visible', 'có thể nhìn thấy; rõ rệt', 'adjective', '[{"en":"The mountains are visible from our hotel window on clear days.","vi":"Vào những ngày trời quang, có thể nhìn thấy núi từ cửa sổ khách sạn của chúng tôi."},{"en":"The stars are barely visible in big cities because of the lights.","vi":"Ở các thành phố lớn, hầu như không nhìn thấy sao vì ánh đèn."},{"en":"There has been a visible improvement in his work this month.","vi":"Tháng này, công việc của anh ấy có sự tiến bộ rõ rệt."}]', '[{"phrase":"clearly visible"},{"phrase":"barely visible"},{"phrase":"visible from"}]', NULL, '/ˈvɪzəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visib/visible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-14', 30, 'electric', '(chạy bằng) điện; sôi động', 'adjective', '[{"en":"We''re thinking about buying an electric car next year.","vi":"Chúng tôi đang tính mua một chiếc ô tô điện vào năm sau."},{"en":"Be careful, that old electric heater gets very hot.","vi":"Cẩn thận nhé, cái máy sưởi điện cũ đó nóng lắm."},{"en":"The atmosphere at the concert last night was electric.","vi":"Bầu không khí tại buổi hòa nhạc tối qua vô cùng sôi động."}]', '[{"phrase":"electric car"},{"phrase":"electric guitar"},{"phrase":"electric shock"}]', 'electric (chạy bằng điện) ≠ electrical (thuộc về điện nói chung)', '/ɪˈlektrɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electric__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-15', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 15', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 15);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 1, 'impressive', 'ấn tượng; gây ấn tượng mạnh', 'adjective', '[{"en":"Your English has improved a lot; it''s really impressive.","vi":"Tiếng Anh của bạn tiến bộ nhiều lắm, thật sự rất ấn tượng."},{"en":"The hotel had an impressive view of the old city.","vi":"Khách sạn có tầm nhìn ấn tượng ra khu phố cổ."},{"en":"She gave an impressive performance at her first concert.","vi":"Cô ấy đã có một màn trình diễn ấn tượng trong buổi hòa nhạc đầu tiên."}]', '[{"phrase":"very impressive"},{"phrase":"impressive performance"},{"phrase":"impressive results"},{"phrase":"impressive view"}]', NULL, '/ɪmˈpresɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impressive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 2, 'evolution', 'sự tiến hóa; sự phát triển', 'noun', '[{"en":"Our teacher explained the theory of evolution in a simple way.","vi":"Thầy giáo giải thích thuyết tiến hóa một cách đơn giản."},{"en":"Scientists study the evolution of birds from small dinosaurs.","vi":"Các nhà khoa học nghiên cứu sự tiến hóa của loài chim từ những con khủng long nhỏ."},{"en":"The museum shows the evolution of the telephone over a hundred years.","vi":"Bảo tàng giới thiệu sự phát triển của chiếc điện thoại qua một trăm năm."}]', '[{"phrase":"theory of evolution"},{"phrase":"human evolution"},{"phrase":"evolution of"}]', NULL, '/ˌevəˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolu/evolution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 3, 'awareness', 'nhận thức; sự hiểu biết', 'noun', '[{"en":"The campaign aims to raise awareness of the dangers of smoking.","vi":"Chiến dịch nhằm nâng cao nhận thức về tác hại của việc hút thuốc."},{"en":"There is growing awareness that sleep is important for health.","vi":"Ngày càng có nhiều người nhận thức rằng giấc ngủ quan trọng đối với sức khỏe."},{"en":"Children need more awareness of road safety when they walk to school.","vi":"Trẻ em cần hiểu biết hơn về an toàn giao thông khi đi bộ đến trường."}]', '[{"phrase":"raise awareness"},{"phrase":"public awareness"},{"phrase":"growing awareness"},{"phrase":"awareness of"}]', 'awareness of sth', '/əˈwernəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/awareness__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 4, 'violent', 'bạo lực; dữ dội', 'adjective', '[{"en":"Parents worry that some video games are too violent for kids.","vi":"Cha mẹ lo rằng một số trò chơi điện tử quá bạo lực đối với trẻ em."},{"en":"A violent storm knocked down trees across the town last night.","vi":"Tối qua một cơn bão dữ dội đã quật đổ cây cối khắp thị trấn."},{"en":"I don''t like watching violent movies before I go to bed.","vi":"Tôi không thích xem phim bạo lực trước khi đi ngủ."}]', '[{"phrase":"violent storm"},{"phrase":"violent crime"},{"phrase":"violent behavior"}]', NULL, '/ˈvaɪələnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viole/violent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 5, 'slave', 'nô lệ', 'noun', '[{"en":"The old house was built by slaves more than two hundred years ago.","vi":"Ngôi nhà cổ này được những người nô lệ xây dựng cách đây hơn hai trăm năm."},{"en":"In the story, the young slave finally wins his freedom.","vi":"Trong câu chuyện, người nô lệ trẻ cuối cùng cũng giành được tự do."},{"en":"Don''t become a slave to your phone; put it away sometimes.","vi":"Đừng trở thành nô lệ của điện thoại; thỉnh thoảng hãy cất nó đi."}]', '[{"phrase":"slave trade"},{"phrase":"former slave"},{"phrase":"slave to"}]', NULL, '/sleɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sla/slave/slave__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 6, 'wealthy', 'giàu có', 'adjective', '[{"en":"Her grandparents were wealthy farmers who owned a lot of land.","vi":"Ông bà cô ấy là những nông dân giàu có sở hữu rất nhiều đất."},{"en":"Only wealthy families could send their children to study abroad back then.","vi":"Hồi đó chỉ những gia đình giàu có mới có thể cho con đi du học."},{"en":"He became wealthy after selling his small company.","vi":"Ông ấy trở nên giàu có sau khi bán công ty nhỏ của mình."}]', '[{"phrase":"wealthy family"},{"phrase":"wealthy people"},{"phrase":"become wealthy"}]', NULL, '/ˈwelθi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wealt/wealthy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 7, 'architecture', 'kiến trúc; ngành kiến trúc', 'noun', '[{"en":"We walked around the old town admiring the beautiful architecture.","vi":"Chúng tôi đi dạo quanh phố cổ, ngắm nhìn kiến trúc tuyệt đẹp."},{"en":"My sister is studying architecture at university.","vi":"Chị tôi đang học ngành kiến trúc ở trường đại học."},{"en":"The city is famous for its modern architecture and wide streets.","vi":"Thành phố nổi tiếng với kiến trúc hiện đại và những con phố rộng."}]', '[{"phrase":"modern architecture"},{"phrase":"study architecture"},{"phrase":"school of architecture"}]', 'không đếm được', '/ˈɑːrkɪtektʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arc/archi/architecture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 8, 'acceptable', 'chấp nhận được; tạm được', 'adjective', '[{"en":"Is it acceptable to wear jeans to the office?","vi":"Mặc quần jean đến văn phòng có được chấp nhận không?"},{"en":"The food was acceptable, but nothing special.","vi":"Đồ ăn tạm được, nhưng không có gì đặc biệt."},{"en":"Shouting at your coworkers is not acceptable behavior.","vi":"La hét với đồng nghiệp là hành vi không thể chấp nhận được."}]', '[{"phrase":"perfectly acceptable"},{"phrase":"socially acceptable"},{"phrase":"acceptable behavior"},{"phrase":"acceptable to"}]', NULL, '/əkˈseptəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accep/acceptable__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 9, 'journal', 'tạp chí (chuyên ngành); nhật ký', 'noun', '[{"en":"Her research was published in a medical journal last year.","vi":"Nghiên cứu của cô ấy được đăng trên một tạp chí y khoa vào năm ngoái."},{"en":"I keep a journal and write in it every night.","vi":"Tôi có một cuốn nhật ký và viết vào đó mỗi tối."},{"en":"The professor asked us to read two articles from a science journal.","vi":"Giáo sư yêu cầu chúng tôi đọc hai bài báo trên một tạp chí khoa học."}]', '[{"phrase":"keep a journal"},{"phrase":"medical journal"},{"phrase":"academic journal"}]', NULL, '/ˈdʒɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 10, 'coal', 'than đá', 'noun', '[{"en":"The town grew rich from its coal mines.","vi":"Thị trấn trở nên giàu có nhờ các mỏ than."},{"en":"Many power plants still burn coal to make electricity.","vi":"Nhiều nhà máy điện vẫn đốt than để sản xuất điện."},{"en":"My grandfather used to cook on a small coal stove.","vi":"Ngày xưa ông tôi từng nấu ăn bằng một cái bếp than nhỏ."}]', '[{"phrase":"coal mine"},{"phrase":"burn coal"},{"phrase":"coal miner"},{"phrase":"coal industry"}]', 'không đếm được', '/kəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coal_/coal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 11, 'measurement', 'sự đo lường; số đo; kích thước', 'noun', '[{"en":"The tailor took my measurements for the new suit.","vi":"Người thợ may lấy số đo của tôi để may bộ vest mới."},{"en":"Accurate measurement is very important in science experiments.","vi":"Việc đo lường chính xác rất quan trọng trong các thí nghiệm khoa học."},{"en":"Check the measurements of the room before you buy a sofa.","vi":"Hãy kiểm tra kích thước căn phòng trước khi mua ghế sofa."}]', '[{"phrase":"take measurements"},{"phrase":"accurate measurement"},{"phrase":"unit of measurement"}]', NULL, '/ˈmeʒərmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/measu/measurement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 12, 'random', 'ngẫu nhiên; tùy tiện', 'adjective', '[{"en":"The computer picks a random number between one and ten.","vi":"Máy tính chọn một số ngẫu nhiên từ một đến mười."},{"en":"We asked random people on the street about their favorite food.","vi":"Chúng tôi hỏi ngẫu nhiên những người trên phố về món ăn yêu thích của họ."},{"en":"The winners will be chosen at random next Friday.","vi":"Người thắng cuộc sẽ được chọn ngẫu nhiên vào thứ Sáu tới."}]', '[{"phrase":"at random"},{"phrase":"random number"},{"phrase":"random sample"},{"phrase":"completely random"}]', NULL, '/ˈrændəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rando/random__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 13, 'successfully', 'thành công; một cách thành công', 'adverb', '[{"en":"She successfully passed her driving test on the first try.","vi":"Cô ấy đã vượt qua kỳ thi lái xe thành công ngay lần đầu tiên."},{"en":"The doctors successfully completed the operation in three hours.","vi":"Các bác sĩ đã hoàn thành ca phẫu thuật thành công trong ba giờ."},{"en":"Our team successfully launched the new website last month.","vi":"Nhóm chúng tôi đã ra mắt trang web mới thành công vào tháng trước."}]', '[{"phrase":"successfully complete"},{"phrase":"successfully launch"},{"phrase":"successfully pass"}]', NULL, '/səkˈsesfəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successfully__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 14, 'depress', 'làm chán nản; làm buồn; làm giảm (giá, lương)', 'verb', '[{"en":"Rainy weather in the winter always depresses me.","vi":"Thời tiết mưa vào mùa đông luôn làm tôi thấy chán nản."},{"en":"It depresses me to see so much trash on the beach.","vi":"Tôi thấy buồn khi nhìn thấy quá nhiều rác trên bãi biển."},{"en":"Rising unemployment can depress wages across the whole country.","vi":"Tỷ lệ thất nghiệp tăng có thể làm giảm tiền lương trên cả nước."}]', '[{"phrase":"depress prices"},{"phrase":"depress wages"},{"phrase":"depress demand"}]', 'hay gặp: depressed (buồn chán), depressing (gây buồn chán)', '/dɪˈpres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 15, 'illustration', 'hình minh họa; ví dụ minh họa', 'noun', '[{"en":"The children''s book has colorful illustrations on every page.","vi":"Cuốn sách thiếu nhi có hình minh họa đầy màu sắc trên mỗi trang."},{"en":"Let me give you a simple illustration of how this works.","vi":"Để tôi đưa ra một ví dụ minh họa đơn giản về cách việc này hoạt động."},{"en":"She earns money by drawing illustrations for magazines.","vi":"Cô ấy kiếm tiền bằng cách vẽ tranh minh họa cho các tạp chí."}]', '[{"phrase":"colorful illustrations"},{"phrase":"clear illustration"},{"phrase":"illustration of"}]', NULL, '/ˌɪləˈstreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustration__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 16, 'burst', 'vỡ; nổ; bật (khóc, cười)', 'verb', '[{"en":"The balloon burst when my little brother sat on it.","vi":"Quả bóng bay nổ khi em trai tôi ngồi lên nó."},{"en":"A water pipe burst in our kitchen last night.","vi":"Tối qua một ống nước trong bếp nhà tôi bị vỡ."},{"en":"She burst into tears when she heard the good news.","vi":"Cô ấy bật khóc khi nghe tin vui."}]', '[{"phrase":"burst into tears"},{"phrase":"burst out laughing"},{"phrase":"burst pipe"}]', 'burst – burst – burst', '/bɜːrst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burst/burst__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 17, 'privilege', 'đặc quyền; quyền lợi đặc biệt; vinh dự', 'noun', '[{"en":"It was a privilege to work with such talented people.","vi":"Được làm việc với những người tài năng như vậy là một vinh dự."},{"en":"Senior staff enjoy special privileges like free parking.","vi":"Nhân viên cấp cao được hưởng những quyền lợi đặc biệt như đỗ xe miễn phí."},{"en":"Education should be a right, not a privilege.","vi":"Giáo dục nên là một quyền, không phải một đặc quyền."}]', '[{"phrase":"great privilege"},{"phrase":"special privileges"},{"phrase":"have the privilege of"}]', NULL, '/ˈprɪvəlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/privi/privilege__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 18, 'buyer', 'người mua', 'noun', '[{"en":"We finally found a buyer for our old car.","vi":"Cuối cùng chúng tôi cũng tìm được người mua chiếc xe cũ."},{"en":"First-time home buyers often need help from their parents.","vi":"Những người lần đầu mua nhà thường cần bố mẹ giúp đỡ."},{"en":"The buyer asked for a lower price before signing.","vi":"Người mua đề nghị giảm giá trước khi ký."}]', '[{"phrase":"find a buyer"},{"phrase":"first-time buyer"},{"phrase":"potential buyer"},{"phrase":"home buyer"}]', NULL, '/ˈbaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/buy/buyer/buyer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 19, 'mutual', 'lẫn nhau; chung', 'adjective', '[{"en":"We met through a mutual friend at a party.","vi":"Chúng tôi quen nhau qua một người bạn chung trong một bữa tiệc."},{"en":"A good marriage is built on mutual respect.","vi":"Một cuộc hôn nhân tốt đẹp được xây dựng trên sự tôn trọng lẫn nhau."},{"en":"The decision to end the partnership was mutual.","vi":"Việc chấm dứt hợp tác là quyết định chung của cả hai bên."}]', '[{"phrase":"mutual friend"},{"phrase":"mutual respect"},{"phrase":"mutual understanding"},{"phrase":"mutual benefit"}]', NULL, '/ˈmjuːtʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mut/mutua/mutual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 20, 'rail', 'đường sắt; tay vịn; thanh ray', 'noun', '[{"en":"Traveling by rail is cheaper than flying in this country.","vi":"Ở nước này, đi bằng tàu hỏa rẻ hơn đi máy bay."},{"en":"Hold on to the rail when you go down the stairs.","vi":"Hãy bám vào tay vịn khi đi xuống cầu thang."},{"en":"The city plans to build a new rail line to the airport.","vi":"Thành phố dự định xây một tuyến đường sắt mới đến sân bay."}]', '[{"phrase":"by rail"},{"phrase":"rail line"},{"phrase":"rail network"},{"phrase":"rail travel"}]', NULL, '/reɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/rail_/rail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 21, 'motivate', 'thúc đẩy; tạo động lực', 'verb', '[{"en":"A good teacher knows how to motivate students.","vi":"Một giáo viên giỏi biết cách tạo động lực cho học sinh."},{"en":"What motivated you to start learning English?","vi":"Điều gì đã thúc đẩy bạn bắt đầu học tiếng Anh?"},{"en":"She is highly motivated to finish her degree this year.","vi":"Cô ấy rất có động lực để hoàn thành chương trình học trong năm nay."}]', '[{"phrase":"motivate students"},{"phrase":"motivate employees"},{"phrase":"highly motivated"}]', NULL, '/ˈməʊtɪveɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motivate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 22, 'laboratory', 'phòng thí nghiệm; phòng xét nghiệm', 'noun', '[{"en":"The samples were sent to a laboratory for testing.","vi":"Các mẫu được gửi đến phòng thí nghiệm để xét nghiệm."},{"en":"Students must wear safety glasses in the chemistry laboratory.","vi":"Học sinh phải đeo kính bảo hộ trong phòng thí nghiệm hóa học."},{"en":"My mother works in a hospital laboratory.","vi":"Mẹ tôi làm việc trong phòng xét nghiệm của một bệnh viện."}]', '[{"phrase":"research laboratory"},{"phrase":"science laboratory"},{"phrase":"laboratory test"}]', 'viết tắt: lab', '/ˈlæbrətɔːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/labor/laboratory__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 23, 'mortgage', 'khoản vay thế chấp (mua nhà)', 'noun', '[{"en":"They took out a mortgage to buy their first home.","vi":"Họ vay thế chấp để mua ngôi nhà đầu tiên."},{"en":"We pay our mortgage on the first day of each month.","vi":"Chúng tôi trả tiền vay mua nhà vào ngày đầu tiên của mỗi tháng."},{"en":"It will take us twenty years to pay off the mortgage.","vi":"Chúng tôi sẽ mất hai mươi năm để trả hết khoản vay thế chấp."}]', '[{"phrase":"take out a mortgage"},{"phrase":"pay off a mortgage"},{"phrase":"mortgage payment"},{"phrase":"mortgage rate"}]', NULL, '/ˈmɔːrɡɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/mortg/mortgage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 24, 'promotion', 'sự thăng chức; khuyến mãi; sự quảng bá', 'noun', '[{"en":"He got a promotion after working here for three years.","vi":"Anh ấy được thăng chức sau ba năm làm việc ở đây."},{"en":"The store is running a special promotion on summer clothes.","vi":"Cửa hàng đang có chương trình khuyến mãi đặc biệt cho quần áo mùa hè."},{"en":"Social media is useful for the promotion of small businesses.","vi":"Mạng xã hội rất hữu ích cho việc quảng bá các doanh nghiệp nhỏ."}]', '[{"phrase":"get a promotion"},{"phrase":"sales promotion"},{"phrase":"special promotion"}]', NULL, '/prəˈməʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promotion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 25, 'passion', 'niềm đam mê; tình cảm mãnh liệt', 'noun', '[{"en":"Cooking has been my passion since I was a child.","vi":"Nấu ăn là niềm đam mê của tôi từ khi còn nhỏ."},{"en":"He talks about music with real passion.","vi":"Anh ấy nói về âm nhạc với niềm đam mê thật sự."},{"en":"She has a passion for helping animals in need.","vi":"Cô ấy có niềm đam mê giúp đỡ những con vật gặp khó khăn."}]', '[{"phrase":"passion for"},{"phrase":"real passion"},{"phrase":"follow your passion"},{"phrase":"share a passion"}]', 'passion for sth', '/ˈpæʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passi/passion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 26, 'champion', 'nhà vô địch; người đấu tranh (cho điều gì)', 'noun', '[{"en":"Our school team became the national champion last year.","vi":"Năm ngoái đội trường chúng tôi đã trở thành nhà vô địch quốc gia."},{"en":"The world champion will defend her title next month.","vi":"Nhà vô địch thế giới sẽ bảo vệ danh hiệu của mình vào tháng tới."},{"en":"She has long been a champion of children''s education.","vi":"Bà ấy từ lâu đã là người đấu tranh cho giáo dục trẻ em."}]', '[{"phrase":"world champion"},{"phrase":"national champion"},{"phrase":"defending champion"},{"phrase":"champion of"}]', NULL, '/ˈtʃæmpiən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/champ/champion__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 27, 'fulfill', 'thực hiện (ước mơ, lời hứa); đáp ứng', 'verb', '[{"en":"He finally fulfilled his dream of visiting Japan.","vi":"Cuối cùng anh ấy đã thực hiện được ước mơ đến thăm Nhật Bản."},{"en":"Always fulfill your promises, even the small ones.","vi":"Hãy luôn thực hiện lời hứa của mình, kể cả những lời hứa nhỏ."},{"en":"The new building does not fulfill the safety requirements.","vi":"Tòa nhà mới không đáp ứng các yêu cầu về an toàn."}]', '[{"phrase":"fulfill a dream"},{"phrase":"fulfill a promise"},{"phrase":"fulfill requirements"},{"phrase":"fulfill a need"}]', 'Mỹ: fulfill · Anh: fulfil', '/fʊˈlfɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 28, 'dust', 'bụi', 'noun', '[{"en":"The old books on the shelf were covered in dust.","vi":"Những cuốn sách cũ trên kệ phủ đầy bụi."},{"en":"I''m allergic to dust, so I clean my room often.","vi":"Tôi bị dị ứng với bụi nên thường xuyên dọn phòng."},{"en":"A cloud of dust rose behind the truck on the dirt road.","vi":"Một đám bụi bốc lên phía sau chiếc xe tải trên con đường đất."}]', '[{"phrase":"covered in dust"},{"phrase":"cloud of dust"},{"phrase":"dust allergy"}]', 'không đếm được', '/dʌst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dus/dust_/dust__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 29, 'dedicate', 'cống hiến; dành (cho); đề tặng', 'verb', '[{"en":"She dedicated her life to helping poor children.","vi":"Bà ấy đã cống hiến cả cuộc đời để giúp đỡ trẻ em nghèo."},{"en":"The company dedicates one day a month to staff training.","vi":"Công ty dành một ngày mỗi tháng cho việc đào tạo nhân viên."},{"en":"I would like to dedicate this song to my mother.","vi":"Tôi xin dành tặng bài hát này cho mẹ tôi."}]', '[{"phrase":"dedicate your life to"},{"phrase":"dedicate time to"},{"phrase":"dedicate a song to"}]', 'dedicate sth to sb/sth', '/ˈdedɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/ded/dedic/dedicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-15', 30, 'roughly', 'khoảng, xấp xỉ; thô bạo, mạnh tay', 'adverb', '[{"en":"The trip takes roughly two hours by car.","vi":"Chuyến đi mất khoảng hai tiếng bằng ô tô."},{"en":"Roughly half of the students live on campus.","vi":"Khoảng một nửa số sinh viên sống trong khuôn viên trường."},{"en":"Please don''t handle the boxes roughly; there are glasses inside.","vi":"Xin đừng mạnh tay với các thùng hàng; bên trong có ly thủy tinh."}]', '[{"phrase":"roughly speaking"},{"phrase":"roughly half"},{"phrase":"roughly the same"},{"phrase":"treat someone roughly"}]', NULL, '/ˈrʌfli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/rough/roughly__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-16', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 16', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 16);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 1, 'skirt', 'váy; chân váy', 'noun', '[{"en":"She bought a long blue skirt for the summer party.","vi":"Cô ấy mua một chiếc váy dài màu xanh để đi dự tiệc mùa hè."},{"en":"This skirt is too short for a job interview.","vi":"Chiếc chân váy này quá ngắn để đi phỏng vấn xin việc."},{"en":"My sister wears a skirt to work most days.","vi":"Hầu như ngày nào chị tôi cũng mặc váy đi làm."}]', '[{"phrase":"long skirt"},{"phrase":"short skirt"},{"phrase":"wear a skirt"}]', NULL, '/skɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skirt/skirt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 2, 'province', 'tỉnh', 'noun', '[{"en":"My grandparents live in a small village in the north of the province.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ phía bắc tỉnh."},{"en":"Canada has ten provinces and three territories.","vi":"Canada có mười tỉnh bang và ba vùng lãnh thổ."},{"en":"The new highway connects our province to the capital.","vi":"Đường cao tốc mới nối tỉnh chúng tôi với thủ đô."}]', '[{"phrase":"in the province"},{"phrase":"northern province"},{"phrase":"coastal province"}]', NULL, '/ˈprɑːvɪns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/province__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 3, 'march', 'diễu hành; hành quân', 'verb', '[{"en":"The band marched through the town on the holiday.","vi":"Ban nhạc diễu hành qua thị trấn vào ngày lễ."},{"en":"The soldiers marched for hours in the heavy rain.","vi":"Những người lính hành quân hàng giờ dưới mưa lớn."},{"en":"The students marched into the hall in two neat lines.","vi":"Học sinh xếp thành hai hàng ngay ngắn tiến vào hội trường."}]', '[{"phrase":"march through"},{"phrase":"march into"},{"phrase":"march down the street"}]', 'Viết hoa March = tháng Ba', '/mɑːrtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/march/march__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 4, 'evaluation', 'sự đánh giá', 'noun', '[{"en":"Every employee gets a performance evaluation at the end of the year.","vi":"Mỗi nhân viên đều được đánh giá hiệu quả công việc vào cuối năm."},{"en":"The teacher''s evaluation of my essay was very helpful.","vi":"Lời đánh giá của cô giáo về bài luận của tôi rất hữu ích."},{"en":"We need a careful evaluation of the costs before we decide.","vi":"Chúng ta cần đánh giá kỹ các chi phí trước khi quyết định."}]', '[{"phrase":"performance evaluation"},{"phrase":"careful evaluation"},{"phrase":"evaluation of"}]', NULL, '/ɪˌvæljuˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 5, 'compromise', 'sự thỏa hiệp; sự nhượng bộ', 'noun', '[{"en":"After a long discussion, we finally reached a compromise.","vi":"Sau một cuộc thảo luận dài, cuối cùng chúng tôi đã đi đến thỏa hiệp."},{"en":"Eating at home on Saturday was a fair compromise for both of us.","vi":"Ăn ở nhà vào thứ Bảy là một sự thỏa hiệp hợp lý cho cả hai chúng tôi."},{"en":"Every good marriage needs some compromise from both sides.","vi":"Cuộc hôn nhân tốt nào cũng cần sự nhượng bộ từ cả hai phía."}]', '[{"phrase":"reach a compromise"},{"phrase":"make compromises"},{"phrase":"fair compromise"}]', NULL, '/ˈkɑːmprəmaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/compromise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 6, 'accomplish', 'hoàn thành; đạt được', 'verb', '[{"en":"We accomplished a lot at work this week.","vi":"Tuần này chúng tôi đã hoàn thành được nhiều việc ở công ty."},{"en":"She finally accomplished her goal of running a marathon.","vi":"Cuối cùng cô ấy đã đạt được mục tiêu chạy một cuộc marathon."},{"en":"What do you hope to accomplish in your first year of college?","vi":"Bạn hy vọng đạt được điều gì trong năm đầu đại học?"}]', '[{"phrase":"accomplish a goal"},{"phrase":"accomplish a task"},{"phrase":"accomplish a lot"}]', NULL, '/əˈkɑːmplɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accomplish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 7, 'weakness', 'điểm yếu; sự yếu ớt', 'noun', '[{"en":"Everyone has strengths and weaknesses, so don''t be too hard on yourself.","vi":"Ai cũng có điểm mạnh và điểm yếu, nên đừng quá khắt khe với bản thân."},{"en":"My biggest weakness is that I talk too much in meetings.","vi":"Điểm yếu lớn nhất của tôi là nói quá nhiều trong các cuộc họp."},{"en":"After the fever, he felt a strange weakness in his legs.","vi":"Sau cơn sốt, anh ấy thấy chân yếu đi một cách lạ thường."}]', '[{"phrase":"strengths and weaknesses"},{"phrase":"biggest weakness"},{"phrase":"have a weakness for"}]', NULL, '/ˈwiːknəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weakn/weakness__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 8, 'announcement', 'thông báo; lời công bố', 'noun', '[{"en":"Please listen carefully to the announcement about the train delay.","vi":"Xin hãy nghe kỹ thông báo về việc tàu bị trễ."},{"en":"The company made an announcement about new working hours.","vi":"Công ty đã ra thông báo về giờ làm việc mới."},{"en":"Their wedding announcement surprised all of their friends.","vi":"Việc họ công bố đám cưới khiến tất cả bạn bè bất ngờ."}]', '[{"phrase":"make an announcement"},{"phrase":"official announcement"},{"phrase":"announcement about"}]', NULL, '/əˈnaʊnsmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annou/announcement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 9, 'salt', 'muối', 'noun', '[{"en":"Could you pass me the salt, please?","vi":"Bạn đưa giúp tôi lọ muối được không?"},{"en":"Add a pinch of salt to the boiling water.","vi":"Cho một nhúm muối vào nước đang sôi."},{"en":"Eating too much salt is bad for your heart.","vi":"Ăn quá nhiều muối có hại cho tim."}]', '[{"phrase":"a pinch of salt"},{"phrase":"salt and pepper"},{"phrase":"sea salt"}]', 'không đếm được', '/sɔːlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/salt_/salt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 10, 'glance', 'liếc nhìn; nhìn lướt qua', 'verb', '[{"en":"She glanced at her watch and hurried out of the room.","vi":"Cô ấy liếc nhìn đồng hồ rồi vội vã ra khỏi phòng."},{"en":"He glanced through the menu and ordered a coffee.","vi":"Anh ấy nhìn lướt qua thực đơn rồi gọi một ly cà phê."},{"en":"I glanced back and saw my dog following me.","vi":"Tôi liếc nhìn lại phía sau và thấy con chó đang đi theo mình."}]', '[{"phrase":"glance at"},{"phrase":"glance through"},{"phrase":"glance back"}]', NULL, '/ɡlæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glanc/glance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 11, 'opera', 'nhạc kịch opera', 'noun', '[{"en":"My parents love going to the opera on special occasions.","vi":"Bố mẹ tôi thích đi xem opera vào những dịp đặc biệt."},{"en":"She has sung in several famous operas around the world.","vi":"Cô ấy đã hát trong nhiều vở opera nổi tiếng trên khắp thế giới."},{"en":"The opera house in our city is beautiful at night.","vi":"Nhà hát opera ở thành phố chúng tôi về đêm rất đẹp."}]', '[{"phrase":"opera house"},{"phrase":"opera singer"},{"phrase":"go to the opera"}]', NULL, '/ˈɑːprə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/opera__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 12, 'contest', 'cuộc thi', 'noun', '[{"en":"My daughter won first prize in a singing contest.","vi":"Con gái tôi đã đoạt giải nhất trong một cuộc thi hát."},{"en":"The school holds a writing contest every spring.","vi":"Mùa xuân nào trường cũng tổ chức một cuộc thi viết."},{"en":"He entered the photo contest but didn''t win anything.","vi":"Anh ấy tham gia cuộc thi ảnh nhưng không đoạt giải nào."}]', '[{"phrase":"win a contest"},{"phrase":"enter a contest"},{"phrase":"singing contest"}]', NULL, '/ˈkɑːntest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 13, 'brush', 'chải; đánh (răng); phủi', 'verb', '[{"en":"Don''t forget to brush your teeth before bed.","vi":"Đừng quên đánh răng trước khi đi ngủ."},{"en":"She brushed her daughter''s hair every morning before school.","vi":"Sáng nào cô ấy cũng chải tóc cho con gái trước khi đi học."},{"en":"He brushed the snow off his car and drove to work.","vi":"Anh ấy phủi tuyết khỏi xe rồi lái xe đi làm."}]', '[{"phrase":"brush your teeth"},{"phrase":"brush your hair"},{"phrase":"brush off"}]', 'Cũng là danh từ: bàn chải; cái cọ', '/brʌʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bru/brush/brush__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 14, 'embarrass', 'làm xấu hổ; làm ngượng', 'verb', '[{"en":"Please don''t embarrass me in front of my friends.","vi":"Làm ơn đừng làm tôi xấu hổ trước mặt bạn bè."},{"en":"It embarrassed him that he couldn''t remember her name.","vi":"Anh ấy thấy ngượng vì không nhớ nổi tên cô ấy."},{"en":"I was afraid I would embarrass myself during the speech.","vi":"Tôi sợ mình sẽ bị bẽ mặt trong lúc phát biểu."}]', '[{"phrase":"embarrass someone"},{"phrase":"embarrass yourself"}]', 'embarrassed (adj): thấy ngượng · embarrassing (adj): gây ngượng', '/ɪmˈbærəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emb/embar/embarrass__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 15, 'gallery', 'phòng trưng bày (tranh, ảnh)', 'noun', '[{"en":"We spent the afternoon at a small art gallery downtown.","vi":"Chúng tôi dành cả buổi chiều ở một phòng tranh nhỏ trong trung tâm."},{"en":"Her paintings are now shown in a gallery in the city center.","vi":"Tranh của cô ấy hiện được trưng bày tại một phòng tranh ở trung tâm thành phố."},{"en":"The museum''s new gallery is full of old photographs.","vi":"Phòng trưng bày mới của bảo tàng có rất nhiều ảnh cũ."}]', '[{"phrase":"art gallery"},{"phrase":"gallery owner"},{"phrase":"photo gallery"}]', NULL, '/ˈɡæləri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gal/galle/gallery__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 16, 'genetic', '(thuộc) di truyền; (thuộc) gen', 'adjective', '[{"en":"The doctor suggested genetic testing because the disease runs in the family.","vi":"Bác sĩ đề nghị xét nghiệm gen vì căn bệnh này có tính di truyền trong gia đình."},{"en":"Eye color mostly depends on genetic factors.","vi":"Màu mắt chủ yếu phụ thuộc vào yếu tố di truyền."},{"en":"Scientists are studying the genetic differences between these two plants.","vi":"Các nhà khoa học đang nghiên cứu sự khác biệt về gen giữa hai loài cây này."}]', '[{"phrase":"genetic testing"},{"phrase":"genetic factors"},{"phrase":"genetic disease"}]', NULL, '/dʒəˈnetɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/genet/genetic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 17, 'aggressive', 'hung hăng; quyết liệt', 'adjective', '[{"en":"Our neighbor''s dog becomes aggressive when strangers come near the gate.","vi":"Con chó nhà hàng xóm trở nên hung hăng khi người lạ đến gần cổng."},{"en":"He became aggressive and started shouting at the waiter.","vi":"Anh ta trở nên hung hăng và bắt đầu quát tháo người phục vụ."},{"en":"The company is using aggressive marketing to attract young customers.","vi":"Công ty đang tiếp thị quyết liệt để thu hút khách hàng trẻ."}]', '[{"phrase":"aggressive behavior"},{"phrase":"become aggressive"},{"phrase":"aggressive marketing"}]', NULL, '/əˈɡresɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agg/aggre/aggressive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 18, 'chest', 'ngực; cái rương', 'noun', '[{"en":"He felt a sharp pain in his chest while running.","vi":"Anh ấy thấy đau nhói ở ngực khi đang chạy."},{"en":"She held the baby close to her chest.","vi":"Cô ấy ôm đứa bé sát vào ngực."},{"en":"We found old letters in a wooden chest in the attic.","vi":"Chúng tôi tìm thấy những lá thư cũ trong một chiếc rương gỗ trên gác mái."}]', '[{"phrase":"chest pain"},{"phrase":"wooden chest"},{"phrase":"treasure chest"}]', NULL, '/tʃest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chest/chest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 19, 'format', 'định dạng; hình thức', 'noun', '[{"en":"Please send the report in PDF format by Friday.","vi":"Vui lòng gửi báo cáo ở định dạng PDF trước thứ Sáu."},{"en":"My old laptop can''t open this file format.","vi":"Máy tính xách tay cũ của tôi không mở được định dạng tệp này."},{"en":"The show has a new format this season with fewer guests.","vi":"Mùa này chương trình có hình thức mới với ít khách mời hơn."}]', '[{"phrase":"file format"},{"phrase":"digital format"},{"phrase":"new format"}]', NULL, '/ˈfɔːrmæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/format__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 20, 'literary', '(thuộc) văn học', 'adjective', '[{"en":"She writes for a small literary magazine in her free time.","vi":"Lúc rảnh cô ấy viết bài cho một tạp chí văn học nhỏ."},{"en":"The novel won a major literary prize last year.","vi":"Cuốn tiểu thuyết đã đoạt một giải thưởng văn học lớn vào năm ngoái."},{"en":"The writer is famous for her simple literary style.","vi":"Nhà văn ấy nổi tiếng với lối văn giản dị."}]', '[{"phrase":"literary magazine"},{"phrase":"literary prize"},{"phrase":"literary style"}]', NULL, '/ˈlɪtəreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 21, 'govern', 'cai trị; quản lý; chi phối', 'verb', '[{"en":"The king governed the country fairly for forty years.","vi":"Nhà vua đã cai trị đất nước một cách công bằng suốt bốn mươi năm."},{"en":"A board of five members governs the city library.","vi":"Một hội đồng gồm năm thành viên quản lý thư viện thành phố."},{"en":"Strict rules govern the use of the school laboratory.","vi":"Việc sử dụng phòng thí nghiệm của trường chịu sự chi phối của các quy định nghiêm ngặt."}]', '[{"phrase":"govern the country"},{"phrase":"rules governing"},{"phrase":"laws governing"}]', NULL, '/ˈɡʌvərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/govern__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 22, 'embrace', 'ôm; đón nhận', 'verb', '[{"en":"She embraced her son warmly at the airport.","vi":"Cô ấy ôm chầm lấy con trai một cách trìu mến ở sân bay."},{"en":"Our school quickly embraced the new online learning system.","vi":"Trường chúng tôi nhanh chóng đón nhận hệ thống học trực tuyến mới."},{"en":"Older workers are sometimes slow to embrace change.","vi":"Những người lao động lớn tuổi đôi khi chậm đón nhận sự thay đổi."}]', '[{"phrase":"embrace warmly"},{"phrase":"embrace change"},{"phrase":"embrace new ideas"}]', NULL, '/ɪmˈbreɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emb/embra/embrace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 23, 'praise', 'khen ngợi; ca ngợi', 'verb', '[{"en":"The teacher praised her for her hard work.","vi":"Cô giáo khen ngợi bạn ấy vì sự chăm chỉ."},{"en":"Parents should praise their children when they try their best.","vi":"Cha mẹ nên khen con khi chúng cố gắng hết sức."},{"en":"The new restaurant has been highly praised by local food writers.","vi":"Nhà hàng mới được các cây bút ẩm thực địa phương hết lời ca ngợi."}]', '[{"phrase":"praise someone for"},{"phrase":"highly praised"},{"phrase":"widely praised"}]', 'Cũng là danh từ (không đếm được): lời khen', '/preɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/prais/praise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 24, 'silent', 'im lặng; yên tĩnh', 'adjective', '[{"en":"Everyone went silent when the teacher walked in.","vi":"Mọi người im bặt khi thầy giáo bước vào."},{"en":"The house was completely silent after the children went to bed.","vi":"Ngôi nhà hoàn toàn yên tĩnh sau khi bọn trẻ đi ngủ."},{"en":"He stayed silent and didn''t answer my question.","vi":"Anh ấy im lặng và không trả lời câu hỏi của tôi."}]', '[{"phrase":"remain silent"},{"phrase":"go silent"},{"phrase":"completely silent"}]', NULL, '/ˈsaɪlənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silen/silent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 25, 'pump', 'máy bơm; cái bơm', 'noun', '[{"en":"I borrowed a pump from my neighbor to fill my bike tires.","vi":"Tôi mượn hàng xóm cái bơm để bơm lốp xe đạp."},{"en":"The water pump in our building broke again last night.","vi":"Máy bơm nước trong tòa nhà chúng tôi lại hỏng tối qua."},{"en":"He stopped at the gas pump to fill up his car.","vi":"Anh ấy dừng lại ở trụ bơm xăng để đổ đầy xăng cho xe."}]', '[{"phrase":"water pump"},{"phrase":"bicycle pump"},{"phrase":"gas pump"}]', 'Cũng là động từ: bơm', '/pʌmp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pum/pump_/pump__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 26, 'publisher', 'nhà xuất bản', 'noun', '[{"en":"She finally found a publisher for her first novel.","vi":"Cuối cùng cô ấy cũng tìm được nhà xuất bản cho cuốn tiểu thuyết đầu tay."},{"en":"The publisher plans to print ten thousand copies of the book.","vi":"Nhà xuất bản dự định in mười nghìn bản cuốn sách này."},{"en":"He works as an editor at a children''s book publisher.","vi":"Anh ấy làm biên tập viên ở một nhà xuất bản sách thiếu nhi."}]', '[{"phrase":"find a publisher"},{"phrase":"book publisher"},{"phrase":"major publisher"}]', NULL, '/ˈpʌblɪʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publisher__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 27, 'celebration', 'lễ kỷ niệm; sự ăn mừng', 'noun', '[{"en":"We had a small celebration for my grandmother''s eightieth birthday.","vi":"Chúng tôi tổ chức một buổi lễ nhỏ mừng sinh nhật lần thứ tám mươi của bà."},{"en":"The whole town joined the New Year celebrations in the square.","vi":"Cả thị trấn cùng tham gia lễ mừng năm mới ở quảng trường."},{"en":"Passing all your exams is definitely a cause for celebration.","vi":"Đỗ tất cả các kỳ thi chắc chắn là chuyện đáng để ăn mừng."}]', '[{"phrase":"birthday celebration"},{"phrase":"cause for celebration"},{"phrase":"in celebration of"}]', NULL, '/ˌselɪˈbreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/celeb/celebration__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 28, 'golf', 'môn đánh gôn', 'noun', '[{"en":"My father plays golf with his friends every Sunday morning.","vi":"Sáng Chủ nhật nào bố tôi cũng chơi gôn với bạn bè."},{"en":"They built a new golf course near the lake.","vi":"Họ đã xây một sân gôn mới gần hồ."},{"en":"She took golf lessons during her summer vacation.","vi":"Cô ấy đã học chơi gôn trong kỳ nghỉ hè."}]', '[{"phrase":"play golf"},{"phrase":"golf course"},{"phrase":"golf club"}]', 'không đếm được', '/ɡɑːlf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/golf_/golf__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 29, 'compensation', 'tiền bồi thường; sự đền bù; thù lao', 'noun', '[{"en":"The airline offered us compensation for the long delay.","vi":"Hãng hàng không đề nghị bồi thường cho chúng tôi vì chuyến bay trễ lâu."},{"en":"Workers injured on the job can ask for compensation.","vi":"Người lao động bị thương khi làm việc có thể yêu cầu được đền bù."},{"en":"The job offers good compensation and flexible hours.","vi":"Công việc này có thù lao tốt và giờ giấc linh hoạt."}]', '[{"phrase":"compensation for"},{"phrase":"receive compensation"},{"phrase":"pay compensation"}]', 'không đếm được', '/ˌkɑːmpenˈseɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compensation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-16', 30, 'classical', 'cổ điển', 'adjective', '[{"en":"My mother listens to classical music while she cooks.","vi":"Mẹ tôi nghe nhạc cổ điển trong lúc nấu ăn."},{"en":"He studied classical ballet for ten years.","vi":"Anh ấy đã học múa ba lê cổ điển suốt mười năm."},{"en":"The building is designed in a classical style with tall columns.","vi":"Tòa nhà được thiết kế theo phong cách cổ điển với những cột cao."}]', '[{"phrase":"classical music"},{"phrase":"classical ballet"},{"phrase":"classical style"}]', 'classical (cổ điển) ≠ classic (kinh điển)', '/ˈklæsɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classical__us_2.mp3', NULL, NULL);
